/* Section About (réf. abhijitrout.in/#about) : kicker centré, récit poussé à gauche. */

.about {
  background: var(--color-white);
  color: var(--color-black);
  font-family: var(--font-body);
  padding: clamp(7rem, 16vh, 12rem) 7% clamp(9rem, 20vh, 15rem);
  /* Le widget d'appel entre depuis x: 90px (GSAP) : sans clip, ce décalage élargit la page tant qu'il n'est pas révélé. */
  overflow-x: clip;
}

.about__kicker {
  margin: 0 0 clamp(6rem, 14vh, 10rem);
  text-align: center;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

/* La moitié droite n'accueille que le widget d'appel. */
.about__row {
  display: flex;
  align-items: flex-start;
  gap: clamp(2rem, 4vw, 3.5rem);
}

.about__label {
  margin: 0;
  flex: none;
  font-size: 17px;
  font-weight: 400;
}

.about__body {
  display: flex;
  flex-direction: column;
  gap: 1.35em;
  max-width: 560px;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.55;
  letter-spacing: -0.005em;
}

.about__body p {
  margin: 0;
}

.about__body a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.about__body em {
  font-style: italic;
}

/* Surligneur : background-size balayé de 0 à 100 % par GSAP. */
.about__hl {
  background-color: transparent;
  background-image: linear-gradient(color-mix(in srgb, var(--color-accent) 28%, transparent), color-mix(in srgb, var(--color-accent) 28%, transparent));
  background-repeat: no-repeat;
  background-size: 0% 88%;
  background-position: 0 60%;
  color: inherit;
  padding: 0 2px;
  margin: 0 -2px;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

@media (prefers-reduced-motion: reduce) {
  .about__hl {
    background-size: 100% 88%;
  }
}

/* ---- Widget « appel entrant » (moitié droite) ---- */
/* Le wrapper porte l'animation d'arrivée GSAP, la pastille garde sa vibration CSS sans conflit de transform. */
.about__call-wrap {
  margin: auto; /* centré dans l'espace restant à droite */
  align-self: center;
}

.about__call {
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: 9999px; /* GSAP le fait passer à 26px à l'ouverture */
  background: var(--color-black);
  box-shadow: 0 18px 40px color-mix(in srgb, var(--color-black) 28%, transparent);
  overflow: hidden; /* le contenu disparaît pendant repli/ouverture */
  white-space: nowrap;
}

.about__call-head {
  display: inline-flex;
  align-items: center;
  gap: 14px;
}

.about__call--closed .about__call-avatar {
  cursor: pointer;
}

.about__call-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: var(--color-accent);
  color: var(--color-white);
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.04em;
  cursor: default;
}

.about__call-text {
  position: relative;
  display: flex;
  flex: none;
  flex-direction: column;
  margin-right: 26px;
  line-height: 1.25;
}

/* 3 points « quelqu'un écrit », révélés par GSAP avant chaque vibration. */
.about__call-dots {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  opacity: 0;
  visibility: hidden;
}

.about__call-dots i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-gray-600);
  animation: about-dot 0.9s ease-in-out infinite;
}

.about__call-dots i:nth-child(2) {
  animation-delay: 0.15s;
}
.about__call-dots i:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes about-dot {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  40% {
    transform: translateY(-4px);
    opacity: 1;
  }
}

.about__call-hey {
  font-size: 13px;
  color: var(--color-gray-600);
}

.about__call-name {
  font-size: 16px;
  font-weight: 500;
  color: var(--color-white);
}

.about__call-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  cursor: pointer;
}

.about__call-btn--decline {
  background: var(--color-call-decline);
}

.about__call-btn--accept {
  position: relative;
  background: var(--color-call-accept);
}

/* Anneau de sonnerie autour du bouton vert */
.about__call-btn--accept::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--color-call-accept) 55%, transparent);
  animation: about-pulse 1.6s ease-out infinite;
}

@keyframes about-pulse {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  100% {
    transform: scale(1.55);
    opacity: 0;
  }
}

/* ---- Formulaire : hauteur 0 par défaut, GSAP l'étire à l'ouverture ---- */
.about__call-panel {
  height: 0;
  overflow: hidden;
}

.about__call-panel-in {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 4px 4px;
}

/* Croix rouge, écho du bouton raccrocher. */
.about__call-panel-close {
  align-self: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  margin-top: 2px;
  border-radius: 50%;
  background: var(--color-call-decline);
  cursor: pointer;
}

.about__call-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.about__call-field-label {
  font-size: 12px;
  color: var(--color-gray-600);
}

.about__call-field input {
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--color-white) 12%, transparent);
  border-radius: 10px;
  background: var(--color-gray-200);
  font-family: inherit;
  font-size: 14px;
  color: var(--color-white);
}

.about__call-field input::placeholder {
  color: var(--color-gray-500);
}

.about__call-send {
  margin-top: 2px;
  padding: 10px 14px;
  border-radius: 9999px;
  background: var(--color-accent);
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-white);
  cursor: pointer;
}

.about__call-send:disabled {
  opacity: 0.6;
  cursor: wait;
}

@media (prefers-reduced-motion: reduce) {
  .about__call-btn--accept::after,
  .about__call-dots i {
    animation: none;
  }
}

/* ---- Responsive ---- */
@media (max-width: 640px) {
  .about__row {
    flex-direction: column;
    gap: 1.6rem;
  }

  .about__call-wrap {
    align-self: flex-start;
    margin: 2.5rem 0 0;
  }
}

/* Sous 360px, la pastille (325px en largeur naturelle) dépasse la colonne : on resserre boutons et espacements. */
@media (max-width: 359px) {
  .about__call {
    padding: 8px 10px;
  }

  .about__call-head {
    gap: 10px;
  }

  .about__call-avatar,
  .about__call-btn {
    width: 46px;
    height: 46px;
  }

  .about__call-text {
    margin-right: 10px;
  }
}

import { useRef } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { SplitText } from 'gsap/SplitText'
import { useGSAP } from '@gsap/react'
import CallWidget from '@/components/pages/Home/CallWidget'
import { useLocale } from '@/lib/LocaleProvider'
import { ABOUT, type AboutSegment } from '@/data/about'
import '@/components/pages/Home/About.css'

gsap.registerPlugin(ScrollTrigger, SplitText, useGSAP)

function renderSegment(segment: AboutSegment, key: number) {
  if (typeof segment === 'string') return segment
  if ('highlight' in segment)
    return (
      <mark key={key} className="about__hl">
        {segment.highlight}
      </mark>
    )
  if ('link' in segment) {
    return (
      <a key={key} href={segment.href} target="_blank" rel="noopener noreferrer">
        {segment.link}
      </a>
    )
  }
  return <em key={key}>{segment.quote}</em>
}

/* Section About (réf. abhijitrout.in/#about) : planche claire, récit poussé à gauche, widget d'appel à droite. */
export default function About() {
  const root = useRef<HTMLElement>(null)
  const { locale } = useLocale()
  const about = ABOUT[locale]

  useGSAP(
    () => {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

      // autoSplit redécoupe au chargement des polices et au resize, et recrée l'animation rendue par onSplit.
      SplitText.create('.about__kicker', {
        type: 'chars',
        autoSplit: true,
        onSplit: (self) =>
          gsap.from(self.chars, {
            autoAlpha: 0,
            duration: 0.02,
            ease: 'none',
            stagger: 0.045,
            scrollTrigger: { trigger: '.about__kicker', start: 'top 85%', once: true },
          }),
      })

      SplitText.create('.about__body p', {
        type: 'lines',
        mask: 'lines',
        autoSplit: true,
        onSplit: (self) =>
          gsap.from(self.lines, {
            yPercent: 110,
            duration: 0.9,
            ease: 'power4.out',
            stagger: 0.06,
            scrollTrigger: { trigger: '.about__row', start: 'top 75%', once: true },
          }),
      })

      gsap
        .timeline({ scrollTrigger: { trigger: '.about__row', start: 'top 75%', once: true } })
        .from('.about__call-wrap', { x: 90, autoAlpha: 0, duration: 0.9, ease: 'back.out(1.6)' }, 1.2)

      gsap.to('.about__hl', {
        backgroundSize: '100% 88%',
        duration: 0.7,
        ease: 'power2.out',
        stagger: 0.45,
        delay: 0.8,
        scrollTrigger: { trigger: '.about__row', start: 'top 60%', once: true },
      })
    },
    { scope: root },
  )

  return (
    <section className="about" id="about" ref={root}>
      <p className="about__kicker">{about.kicker}</p>

      <div className="about__row">
        <p className="about__label">{about.label}</p>

        <div className="about__body">
          {about.paragraphs.map((paragraph, i) => (
            <p key={i}>{paragraph.map(renderSegment)}</p>
          ))}
        </div>

        <div className="about__call-wrap">
          <CallWidget />
        </div>
      </div>
    </section>
  )
}

import { AnimatePresence, motion } from 'framer-motion'
import { Menu, X } from 'lucide-react'
import { useLocale } from '@/lib/LocaleProvider'
import { HEADER } from '@/data/hero'

type BurgerButtonProps = {
  isOpen: boolean
  onToggle: () => void
}

export default function BurgerButton({ isOpen, onToggle }: BurgerButtonProps) {
  const { locale } = useLocale()
  const Icon = isOpen ? X : Menu

  return (
    <button
      type="button"
      onClick={onToggle}
      aria-expanded={isOpen}
      aria-controls="home-mobile-nav"
      aria-label={isOpen ? HEADER[locale].closeMenuLabel : HEADER[locale].openMenuLabel}
      className="relative flex size-8 shrink-0 cursor-pointer items-center justify-center text-black"
    >
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={isOpen ? 'close' : 'open'}
          initial={{ opacity: 0, rotate: isOpen ? -45 : 45 }}
          animate={{ opacity: 1, rotate: 0 }}
          exit={{ opacity: 0 }}
          transition={{ type: 'spring', stiffness: 500, damping: 60, mass: 1 }}
          className="flex"
        >
          <Icon className="size-7" strokeWidth={1.75} aria-hidden="true" />
        </motion.span>
      </AnimatePresence>
    </button>
  )
}

import { useRef, useState, type FormEvent } from 'react'
import gsap from 'gsap'
import { useGSAP } from '@gsap/react'
import { Phone, X } from 'lucide-react'
import { useLocale } from '@/lib/LocaleProvider'
import { CALL_WIDGET } from '@/data/about'
import { sendContactMessage } from '@/lib/api/contact'

gsap.registerPlugin(useGSAP)

type SendState = 'idle' | 'sending' | 'sent' | 'error'

const RING_BACK_DELAY_MS = 8000

/* Widget « appel entrant » (réf. abhijitrout.in) : refuser replie la pastille sur l'avatar, répondre déplie le formulaire. */
export default function CallWidget() {
  const { locale } = useLocale()
  const callWidget = CALL_WIDGET[locale]
  const pillRef = useRef<HTMLDivElement>(null)
  const collapseTlRef = useRef<gsap.core.Timeline | null>(null)
  const panelTlRef = useRef<gsap.core.Timeline | null>(null)
  const ringLoopRef = useRef<gsap.core.Timeline | null>(null)
  const ringBackRef = useRef<(() => void) | null>(null)
  const ringTimer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const [isClosed, setIsClosed] = useState(false)
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [sendState, setSendState] = useState<SendState>('idle')

  useGSAP(
    (_context, contextSafe) => {
      const pill = pillRef.current!

      const collapsedWidth = () => {
        const avatar = pill.querySelector<HTMLElement>('.about__call-avatar')!
        const pillStyle = getComputedStyle(pill)
        return avatar.offsetWidth + parseFloat(pillStyle.paddingLeft) + parseFloat(pillStyle.paddingRight)
      }

      collapseTlRef.current = gsap
        .timeline({ paused: true })
        .to('.about__call-text, .about__call-btn', {
          autoAlpha: 0,
          x: 18,
          duration: 0.25,
          ease: 'power2.in',
          stagger: 0.05,
        })
        .to(pill, { width: collapsedWidth, duration: 0.45, ease: 'power3.inOut' }, '-=0.05')

      ringBackRef.current = contextSafe!(() => {
        gsap
          .timeline()
          .to(pill, { rotation: 2.2, duration: 0.07, yoyo: true, repeat: 7, ease: 'sine.inOut' })
          .to(pill, { rotation: 0, duration: 0.1 })
      })

      if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        // Les 3 points « tapent » à la place du nom, puis la pastille sonne, en boucle.
        ringLoopRef.current = gsap
          .timeline({ repeat: -1, repeatDelay: 3.4, delay: 1.6 })
          .to('.about__call-hey, .about__call-name', { autoAlpha: 0.12, duration: 0.25 }, 0)
          .to('.about__call-dots', { autoAlpha: 1, duration: 0.25 }, 0)
          .to({}, { duration: 1.0 })
          .to('.about__call-dots', { autoAlpha: 0, duration: 0.2 })
          .to('.about__call-hey, .about__call-name', { autoAlpha: 1, duration: 0.25 }, '<')
          .to(pill, { rotation: 2, duration: 0.07, yoyo: true, repeat: 5, ease: 'sine.inOut' }, '>+0.15')
          .to(pill, { rotation: 0, duration: 0.08 })
      }

      panelTlRef.current = gsap
        .timeline({ paused: true })
        .to(pill, { borderRadius: 26, duration: 0.35, ease: 'power3.inOut' }, 0)
        .fromTo(
          '.about__call-panel',
          { height: 0, autoAlpha: 0 },
          { height: 'auto', autoAlpha: 1, duration: 0.45, ease: 'power3.inOut' },
          0,
        )
        .from(
          '.about__call-panel-in > *',
          { y: 14, autoAlpha: 0, duration: 0.3, ease: 'power2.out', stagger: 0.06 },
          0.18,
        )

      return () => clearTimeout(ringTimer.current)
    },
    { scope: pillRef },
  )

  const close = () => {
    setIsClosed(true)
    setIsFormOpen(false)
    panelTlRef.current?.reverse()
    ringLoopRef.current?.pause(0)
    collapseTlRef.current?.play()
    clearTimeout(ringTimer.current)
    ringTimer.current = setTimeout(() => ringBackRef.current?.(), RING_BACK_DELAY_MS)
  }

  const reopen = () => {
    if (!isClosed) return
    clearTimeout(ringTimer.current)
    setIsClosed(false)
    collapseTlRef.current?.reverse()
    ringLoopRef.current?.play()
  }

  const toggleForm = () => {
    const willOpen = !isFormOpen
    setIsFormOpen(willOpen)
    if (willOpen) {
      setSendState('idle')
      ringLoopRef.current?.pause(0)
      panelTlRef.current?.play()
    } else {
      panelTlRef.current?.reverse()
      ringLoopRef.current?.play()
    }
  }

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    if (sendState === 'sending') return
    const form = e.currentTarget
    const formData = new FormData(form)
    setSendState('sending')
    try {
      await sendContactMessage(String(formData.get('email')), String(formData.get('message')))
      setSendState('sent')
      form.reset()
    } catch {
      setSendState('error')
    }
  }

  return (
    <div
      className={`about__call${isClosed ? ' about__call--closed' : ''}${isFormOpen ? ' is-form-open' : ''}`}
      ref={pillRef}
    >
      <div className="about__call-head">
        <button
          type="button"
          className="about__call-avatar"
          onClick={reopen}
          aria-label={isClosed ? callWidget.ariaReopen : 'Ikhlas'}
        >
          {callWidget.initials}
        </button>
        <span className="about__call-text">
          <span className="about__call-dots" aria-hidden="true">
            <i />
            <i />
            <i />
          </span>
          <span className="about__call-hey">{callWidget.greeting}</span>
          <span className="about__call-name">{callWidget.name}</span>
        </span>
        <button
          type="button"
          className="about__call-btn about__call-btn--decline"
          aria-label={callWidget.ariaDecline}
          onClick={close}
        >
          <X size={20} strokeWidth={2.4} aria-hidden="true" className="text-[var(--color-white)]" />
        </button>
        <button
          type="button"
          className="about__call-btn about__call-btn--accept"
          aria-label={callWidget.ariaAccept}
          aria-expanded={isFormOpen}
          onClick={toggleForm}
        >
          {/* Combiné orienté vers le bas, comme la référence */}
          <Phone size={20} fill="currentColor" strokeWidth={0} aria-hidden="true" className="text-[var(--color-white)]" style={{ transform: 'rotate(135deg)' }} />
        </button>
      </div>

      <form className="about__call-panel" onSubmit={handleSubmit}>
        <div className="about__call-panel-in">
          <label className="about__call-field">
            <span className="about__call-field-label">{callWidget.emailLabel}</span>
            <input type="email" name="email" required placeholder={callWidget.emailPlaceholder} />
          </label>
          <label className="about__call-field">
            <span className="about__call-field-label">{callWidget.messageLabel}</span>
            <input type="text" name="message" required placeholder={callWidget.messagePlaceholder} />
          </label>
          <button type="submit" className="about__call-send" disabled={sendState === 'sending'}>
            {callWidget.sendLabels[sendState]}
          </button>
          <button
            type="button"
            className="about__call-panel-close"
            aria-label={callWidget.ariaCloseForm}
            onClick={toggleForm}
          >
            <X size={14} strokeWidth={2.4} aria-hidden="true" className="text-[var(--color-white)]" />
          </button>
        </div>
      </form>
    </div>
  )
}

/* Section Skills (réf. verteal.com) : roue elliptique de rôles, stack en logos pour la pastille du sommet. */

.vt-team {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  padding-inline: clamp(2rem, 9vw, 11rem);
  background-color: var(--color-white);
  font-family: var(--font-body);
}

.vt-team__stage {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  height: 860px;
  max-height: 85vh;
  min-height: 560px;
  overflow: hidden;
}

/* Titre "ghost" centré au milieu des pastilles */
.vt-team__title {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  margin: 0;
  text-align: center;
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2rem, 7.5vw, 72px);
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--color-black);
  pointer-events: none;
  user-select: none;
  white-space: nowrap;
  z-index: 1;
  animation: vt-breathe 4.5s ease-in-out infinite;
}

/* Respiration du titre, neutralisée par la règle globale prefers-reduced-motion. */
@keyframes vt-breathe {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 0.92;
  }
  50% {
    transform: translate(-50%, -50%) scale(1.02);
    opacity: 1;
  }
}

/* Anneau qui tourne (orbite) autour du titre */
.vt-orbit {
  position: absolute;
  inset: 0;
  transform-origin: center center;
  z-index: 2;
}

/* Chaque emplacement centré ; position sur l'ellipse pilotée par GSAP (x/y). */
.vt-slot {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  will-change: transform;
}

/* Cible du drag : repère écran (aucune rotation) */
.vt-drag {
  cursor: grab;
  will-change: transform;
}
.vt-drag:active {
  cursor: grabbing;
}

/* Wrapper d'entrée (chute + rebond), transform piloté par GSAP */
.vt-enter {
  will-change: transform;
}

/* Wrapper de flottement continu */
.vt-float {
  will-change: transform;
}

.vt-pill {
  display: inline-block;
  padding: 8px 12px;
  border-radius: 9999px;
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.16px;
  white-space: nowrap;
  box-shadow: 0 6px 16px color-mix(in srgb, var(--color-black) 14%, transparent);
  user-select: none;
  transition:
    opacity 0.25s ease,
    translate 0.25s ease,
    box-shadow 0.25s ease;
}

/* translate reste indépendant du rotate inline de chaque pastille. */
.vt-orbit:has(.vt-pill:hover) .vt-pill {
  opacity: 0.45;
}

.vt-orbit .vt-pill:hover {
  opacity: 1;
  translate: 0 -4px;
  box-shadow: 0 12px 26px color-mix(in srgb, var(--color-black) 30%, transparent);
}

/* ---- Tooltip au clic sur une pastille : stack en logos ---- */
.vt-cardback {
  cursor: pointer;
  position: fixed;
  inset: 0;
  z-index: 100;
  background: transparent;
}

/* left/top = centre-haut de la pastille, posés en JS. */
.vt-tip {
  position: fixed;
  transform: translate(-50%, calc(-100% - 14px));
  box-sizing: border-box;
  max-width: min(340px, 90vw);
  padding: 14px 16px;
  background: var(--color-black);
  border: 1px solid color-mix(in srgb, var(--color-white) 10%, transparent);
  border-radius: 14px;
  color: var(--color-white);
  box-shadow: 0 18px 40px color-mix(in srgb, var(--color-black) 45%, transparent);
  animation: vt-tip-in 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* Petite flèche vers le bas pointant la pastille */
.vt-tip__caret {
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: var(--color-black);
  border-right: 1px solid color-mix(in srgb, var(--color-white) 10%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--color-white) 10%, transparent);
  transform: translateX(-50%) rotate(45deg);
}

.vt-card__stack {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px 2px;
}

/* Un logo de techno : gris par défaut, couleur de marque au survol */
.vt-tech {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
}

.vt-tech__ico {
  width: 26px;
  height: 26px;
  color: color-mix(in srgb, var(--color-white) 42%, transparent);
  transition:
    color 0.35s ease,
    transform 0.35s ease;
}
.vt-tech:hover .vt-tech__ico,
.vt-tech.is-active .vt-tech__ico {
  color: var(--tc);
  transform: translateY(-1px);
}

/* Petite infobulle du nom, au-dessus du logo, avec triangle vers le bas */
.vt-tech__tip {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  padding: 4px 8px;
  background: var(--color-gray-200);
  border: 1px solid color-mix(in srgb, var(--color-white) 12%, transparent);
  border-radius: 7px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  color: var(--color-white);
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.2s,
    transform 0.2s;
  z-index: 3;
}
.vt-tech__tip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent;
  border-top-color: var(--color-gray-200);
}
.vt-tech:hover .vt-tech__tip,
.vt-tech.is-active .vt-tech__tip {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

@keyframes vt-tip-in {
  from {
    opacity: 0;
    transform: translate(-50%, calc(-100% - 4px));
  }
  to {
    opacity: 1;
    transform: translate(-50%, calc(-100% - 14px));
  }
}

@media (prefers-reduced-motion: reduce) {
  .vt-float {
    animation: none !important;
  }
  .vt-tip {
    animation: none !important;
  }
}

import { useRef, useEffect, useState, type CSSProperties } from 'react'
import gsap from 'gsap'
import Draggable from 'gsap/Draggable'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { TECH } from '@/components/pages/Home/techIcons'
import { useLocale } from '@/lib/LocaleProvider'
import { ROLES, SKILLS_SECTION } from '@/data/roles'
import '@/components/pages/Home/DedicatedTeam.css'

gsap.registerPlugin(Draggable, ScrollTrigger)

const N = ROLES.en.length
const STEP_ANGLE = 360 / N
const TOP_ANGLE = 270 // sommet de l'ellipse (sin = -1)
const LIGHT_MS = 650 // durée d'allumage par logo
const HOLD_MS = 600 // pause après le dernier logo
const ROTATE_S = 7.5 // durée de rotation par cran
const START_DELAY = 1300 // laisse jouer l'entrée avant de démarrer
const REPEL_RADIUS = 150
const REPEL_PUSH = 34
const FALLBACK_TECH_COLOR = '#B8BEC8'

type TeamControls = {
  manualOpen: (index: number) => void
  close: () => void
  pause: () => void
  resume: () => void
}

/* Roue elliptique des rôles d'Ikhlas (réf. verteal.com) : la pastille du sommet affiche sa stack, puis la roue tourne d'un cran. */
export default function DedicatedTeam() {
  const root = useRef<HTMLElement>(null)
  const controls = useRef<TeamControls | null>(null)
  const { locale } = useLocale()
  const roles = ROLES[locale]
  const [openRoleIndex, setOpenRoleIndex] = useState<number | null>(null)
  const openRole = openRoleIndex === null ? null : roles[openRoleIndex]
  const [anchor, setAnchor] = useState({ x: 0, y: 0 })
  const [activeIdx, setActiveIdx] = useState(0)
  const [isManual, setIsManual] = useState(false)

  const closeCard = () => controls.current?.close()

  useEffect(() => {
    if (!isManual) return
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && closeCard()
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [isManual])

  useEffect(() => {
    const stage = root.current!.querySelector<HTMLElement>('.vt-team__stage')!
    const slots = gsap.utils.toArray<HTMLElement>('.vt-slot', root.current)

    let rx = 0
    let ry = 0
    const measure = () => {
      const rect = stage.getBoundingClientRect()
      rx = Math.min(rect.width * 0.4, 470)
      ry = Math.min(rect.height * 0.27, 205)
    }
    const place = (deg: number) => {
      for (let i = 0; i < N; i++) {
        const a = ((deg + STEP_ANGLE * i) * Math.PI) / 180
        // GSAP perd parfois le translate(-50%) du CSS en lisant la transform : on le fixe pour centrer chaque pastille.
        gsap.set(slots[i], { xPercent: -50, yPercent: -50, x: Math.cos(a) * rx, y: Math.sin(a) * ry })
      }
    }

    measure()
    const drift = { a: TOP_ANGLE }
    place(drift.a)
    window.addEventListener('resize', measure)

    let isAutoRunning = true
    let topIdx = 0
    let timers: ReturnType<typeof setTimeout>[] = []
    let rotTween: gsap.core.Tween | null = null
    const clearTimers = () => {
      timers.forEach(clearTimeout)
      timers = []
    }

    // Ancre le tooltip au-dessus de la pastille et allume ses logos 1 par 1. Rend la durée totale.
    const showStack = (index: number) => {
      const pill = slots[index].querySelector('.vt-pill')!
      const rect = pill.getBoundingClientRect()
      setAnchor({ x: rect.left + rect.width / 2, y: rect.top })
      setActiveIdx(0)
      setOpenRoleIndex(index)
      // Stack identique dans les 2 langues : l'effet monté une seule fois peut lire l'anglais.
      const count = ROLES.en[index].stack.length
      for (let k = 0; k < count; k++) {
        timers.push(setTimeout(() => setActiveIdx(k), k * LIGHT_MS))
      }
      return count * LIGHT_MS + HOLD_MS
    }

    const runAuto = () => {
      if (!isAutoRunning) return
      const duration = showStack(topIdx)
      timers.push(
        setTimeout(() => {
          setOpenRoleIndex(null)
          topIdx = (topIdx - 1 + N) % N
          rotTween = gsap.to(drift, {
            a: drift.a + STEP_ANGLE,
            duration: ROTATE_S,
            ease: 'power2.inOut',
            onUpdate: () => place(drift.a),
            onComplete: runAuto,
          })
        }, duration),
      )
    }

    controls.current = {
      manualOpen(index: number) {
        isAutoRunning = false
        clearTimers()
        rotTween?.kill()
        setIsManual(true)
        showStack(index)
      },
      close() {
        clearTimers()
        setIsManual(false)
        setOpenRoleIndex(null)
        if (!isAutoRunning) {
          isAutoRunning = true
          runAuto()
        }
      },
      pause() {
        isAutoRunning = false
        clearTimers()
        rotTween?.kill()
      },
      resume() {
        if (!isAutoRunning) {
          isAutoRunning = true
          runAuto()
        }
      },
    }

    const ctx = gsap.context(() => {
      gsap.from('.vt-enter', {
        opacity: 0,
        scale: 0.5,
        y: -120,
        duration: 1.1,
        ease: 'elastic.out(1, 0.6)',
        stagger: { each: 0.08, from: 'random' },
        scrollTrigger: { trigger: stage, start: 'top 70%', once: true },
      })

      ScrollTrigger.create({
        trigger: stage,
        start: 'top 70%',
        once: true,
        onEnter: () => {
          timers.push(setTimeout(runAuto, START_DELAY))
        },
      })

      gsap.utils.toArray<HTMLElement>('.vt-float').forEach((el, i) => {
        gsap.to(el, {
          y: gsap.utils.random(-8, -14),
          duration: gsap.utils.random(2.2, 3.4),
          ease: 'sine.inOut',
          repeat: -1,
          yoyo: true,
          delay: i * 0.15,
        })
      })

      // Avant le bloc de répulsion : son return de nettoyage met fin au callback.
      let isDragging = false
      Draggable.create('.vt-drag', {
        type: 'x,y',
        onPress() {
          isDragging = true
          controls.current?.pause()
          setIsManual(false)
          setOpenRoleIndex(null)
          gsap.set((this.target as HTMLElement).closest('.vt-slot'), { zIndex: 30 })
          gsap.to(this.target, { scale: 1.08, duration: 0.2 })
        },
        onClick() {
          const idx = slots.indexOf((this.target as HTMLElement).closest<HTMLElement>('.vt-slot')!)
          if (idx >= 0) controls.current?.manualOpen(idx)
        },
        onRelease() {
          isDragging = false
          gsap.to(this.target, { scale: 1, duration: 0.3, ease: 'back.out(2)' })
        },
        onDragEnd() {
          const slot = (this.target as HTMLElement).closest<HTMLElement>('.vt-slot')!
          gsap.to(this.target, {
            x: 0,
            y: 0,
            duration: 1,
            ease: 'power3.inOut',
            onComplete: () => {
              slot.style.zIndex = ''
            },
          })
          controls.current?.resume()
        },
      })

      // Les pastilles s'écartent du curseur qui approche, puis reviennent sur leur orbite.
      if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        const enters = gsap.utils.toArray<HTMLElement>('.vt-enter')
        const qx = enters.map((el) => gsap.quickTo(el, 'x', { duration: 0.45, ease: 'power3' }))
        const qy = enters.map((el) => gsap.quickTo(el, 'y', { duration: 0.45, ease: 'power3' }))

        const repel = (e: MouseEvent) => {
          if (isDragging) return
          enters.forEach((el, i) => {
            const rect = el.getBoundingClientRect()
            const dx = rect.left + rect.width / 2 - e.clientX
            const dy = rect.top + rect.height / 2 - e.clientY
            const distance = Math.hypot(dx, dy)
            if (distance < REPEL_RADIUS && distance > 0.001) {
              const force = (1 - distance / REPEL_RADIUS) * REPEL_PUSH
              qx[i]((dx / distance) * force)
              qy[i]((dy / distance) * force)
            } else {
              qx[i](0)
              qy[i](0)
            }
          })
        }
        const settle = () =>
          enters.forEach((_, i) => {
            qx[i](0)
            qy[i](0)
          })

        stage.addEventListener('mousemove', repel)
        stage.addEventListener('mouseleave', settle)
        return () => {
          stage.removeEventListener('mousemove', repel)
          stage.removeEventListener('mouseleave', settle)
        }
      }
    }, root)

    return () => {
      clearTimers()
      rotTween?.kill()
      window.removeEventListener('resize', measure)
      ctx.revert()
    }
  }, [])

  return (
    <section className="vt-team" ref={root}>
      <div className="vt-team__stage">
        <h2 className="vt-team__title">{SKILLS_SECTION[locale].title}</h2>

        <div className="vt-orbit">
          {roles.map((role) => (
            <div key={role.id} className="vt-slot">
              <div className="vt-drag" data-role={role.id}>
                <div className="vt-enter">
                  <div className="vt-float">
                    <span className="vt-pill" style={{ backgroundColor: role.color, rotate: `${role.rot}deg` }}>
                      {role.name}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {openRole && (
        <>
          {isManual && <div className="vt-cardback" onClick={closeCard} />}
          <div
            className="vt-tip"
            style={{ left: anchor.x, top: anchor.y, '--accent': openRole.color } as CSSProperties}
          >
            <div className="vt-card__stack">
              {openRole.stack.map((techName, idx) => {
                const tech = TECH[techName]
                const Icon = tech?.Icon
                return (
                  <div
                    className={`vt-tech${idx === activeIdx ? ' is-active' : ''}`}
                    key={techName}
                    style={{ '--tc': tech?.color || FALLBACK_TECH_COLOR } as CSSProperties}
                  >
                    {Icon && <Icon className="vt-tech__ico" />}
                    <span className="vt-tech__tip">{techName}</span>
                  </div>
                )
              })}
            </div>
            <span className="vt-tip__caret" />
          </div>
        </>
      )}
    </section>
  )
}

import { useState, useSyncExternalStore } from 'react'
import { motion, useReducedMotion } from 'framer-motion'
import { isLoaderRevealed, subscribeLoaderReveal } from '@/lib/loaderSession'

type HeroNameProps = {
  name: string
}

const MOUNT_DELAY = 0.2
// Le voile du loader attend 650 ms puis s'efface en 500 ms : le nom part quand il est presque transparent.
const AFTER_LOADER_DELAY = 1.05

/* Nom mis à l'échelle de la largeur comme le fit-text SVG de la réf. viewBox et position du texte mesurées
   sur Cormorant Unicase 400 (encre 1846x181 à 269.149px) : à recalculer quand The Night Watch sera posée. */
export default function HeroName({ name }: HeroNameProps) {
  const isRevealed = useSyncExternalStore(subscribeLoaderReveal, isLoaderRevealed)
  const [wasRevealedOnMount] = useState(isLoaderRevealed)
  const shouldReduceMotion = useReducedMotion()
  const hiddenY = shouldReduceMotion ? 0 : 50
  const delay = wasRevealedOnMount || shouldReduceMotion ? MOUNT_DELAY : AFTER_LOADER_DELAY

  return (
    <div className="flex w-full overflow-clip min-[810px]:px-5 min-[810px]:pb-[46px] min-[1200px]:px-8">
      <motion.h1
        initial={{ opacity: 0.001, y: hiddenY }}
        animate={isRevealed ? { opacity: 1, y: 0 } : { opacity: 0.001, y: hiddenY }}
        transition={{ type: 'spring', stiffness: 130, damping: 30, mass: 0.1, delay }}
        className="w-full"
      >
        <svg viewBox="0 0 1848 240" className="block h-auto w-full" role="img" aria-label={name}>
          <text
            x="-8.4"
            y="232"
            className="fill-black font-heading text-[269.149px] font-normal tracking-[-0.02em] whitespace-pre"
          >
            {name}
          </text>
        </svg>
      </motion.h1>
    </div>
  )
}

import { useRef, useState } from 'react'
import { motion, useMotionValueEvent, useScroll } from 'framer-motion'
import NavPill from '@/components/pages/Home/NavPill'
import LanguageSelect from '@/components/pages/Home/LanguageSelect'
import BurgerButton from '@/components/pages/Home/BurgerButton'
import { HEADER } from '@/data/hero'
import { NAV_LINKS } from '@/data/site'
import { useLocale } from '@/lib/LocaleProvider'
import { shouldHideHeader } from '@/logic/headerVisibility/headerVisibility'

/* Header fixe (réf. haufsess.com) : disparaît en fondu en descendant, revient dès qu'on remonte. Sous le CoinLoader (z-100). */
export default function HomeHeader() {
  const { locale } = useLocale()
  const header = HEADER[locale]
  const links = [header.homeLink, ...NAV_LINKS[locale]]
  const { scrollY } = useScroll()
  const [isHidden, setIsHidden] = useState(false)
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const previousScrollY = useRef(0)

  useMotionValueEvent(scrollY, 'change', (currentScrollY) => {
    const nextIsHidden = shouldHideHeader({
      previousScrollY: previousScrollY.current,
      scrollY: currentScrollY,
      isHidden,
    })
    previousScrollY.current = currentScrollY
    if (nextIsHidden !== isHidden) setIsHidden(nextIsHidden)
  })

  const isVisible = !isHidden || isMenuOpen
  const closeMenu = () => setIsMenuOpen(false)

  return (
    <motion.header
      initial={false}
      animate={{ opacity: isVisible ? 1 : 0 }}
      transition={{ type: 'spring', bounce: 0.2, duration: 0.4 }}
      className={`fixed inset-x-0 top-0 z-[90] bg-white ${isVisible ? '' : 'pointer-events-none'}`}
    >
