import { useLayoutEffect, useMemo, type RefObject } from 'react'
import { createPortal, useFrame, type ThreeEvent } from '@react-three/fiber'
import { useGLTF } from '@react-three/drei'
import { MathUtils, type Group } from 'three'
import ScreenDisplay from '@/components/pages/Home/MacBook/ScreenDisplay'
import type { MacBookMotion, MacBookPhase } from '@/components/pages/Home/MacBook/macBookMotion'

type MacBookModelProps = {
  motion: MacBookMotion
  phase: MacBookPhase
  isZoomed: boolean
  isPoweredOn: boolean
  isShutDown: boolean
  screenAnchor: RefObject<Group | null>
  onOpen: () => void
  onZoomIn: () => void
  onShutDown: () => void
}

// Matériaux du .blend exportés tels quels (logo du capot et légendes des touches en textures) : aucun remplacement ici.
const MODEL_URL = '/models/macbook-pro-14.glb'
const DRACO_PATH = '/draco/'
// Rotation X du nœud Lid : 0 = état exporté (capot à 90°), +π/2 = capot posé sur le clavier.
const LID_CLOSED_ANGLE = Math.PI / 2
const LID_OPEN_ANGLE = -0.14
// Centre du plan Screen dans le repère du nœud Lid.
const SCREEN_CENTER: [number, number, number] = [0, 0.11483, -0.00497]

useGLTF.preload(MODEL_URL, DRACO_PATH)

export default function MacBookModel({
  motion,
  phase,
  isZoomed,
  isPoweredOn,
  isShutDown,
  screenAnchor,
  onOpen,
  onZoomIn,
  onShutDown,
}: MacBookModelProps) {
  const { scene } = useGLTF(MODEL_URL, DRACO_PATH)
  const lid = useMemo(() => scene.getObjectByName('Lid'), [scene])
  const isClickable = phase === 'closed' || (phase === 'open' && !isZoomed)

  useLayoutEffect(() => {
    if (!isClickable) document.body.style.cursor = ''
  }, [isClickable])

  useLayoutEffect(() => () => void (document.body.style.cursor = ''), [])

  useFrame(() => {
    if (lid) lid.rotation.x = MathUtils.lerp(LID_CLOSED_ANGLE, LID_OPEN_ANGLE, motion.lid)
  })

  const handleClick = (event: ThreeEvent<MouseEvent>) => {
    event.stopPropagation()
    if (phase === 'closed') onOpen()
    else if (phase === 'open' && !isZoomed) onZoomIn()
  }

  return (
    <>
      <primitive
        object={scene}
        onClick={handleClick}
        onPointerOver={() => {
          if (isClickable) document.body.style.cursor = 'pointer'
        }}
        onPointerOut={() => {
          document.body.style.cursor = ''
        }}
      />
      {lid &&
        createPortal(
          <group ref={screenAnchor} position={SCREEN_CENTER}>
            {phase === 'open' && (
              <ScreenDisplay
                isPoweredOn={isPoweredOn}
                isInteractive={isZoomed}
                isFitted={isZoomed && !isShutDown}
                onShutDown={onShutDown}
              />
            )}
          </group>,
          lid,
        )}
    </>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { Canvas } from '@react-three/fiber'
import { useMotionValueEvent, useReducedMotion, useScroll } from 'framer-motion'
import { MouseIcon } from 'lucide-react'
import MacBookControls from '@/components/pages/Home/MacBook/MacBookControls'
import MacBookScene from '@/components/pages/Home/MacBook/MacBookScene'
import type { MacBookMotion, MacBookPhase } from '@/components/pages/Home/MacBook/macBookMotion'
import { Button } from '@/components/ui/button'
import { MACBOOK } from '@/data/macbook'
import { useLenis } from '@/lib/LenisProvider'
import { useLocale } from '@/lib/LocaleProvider'
import { ZOOM_RANGE, macBookPoseAt, scrollTopFor } from '@/logic/macBookScroll/macBookScroll'

// À 0,95 de zoom, la caméra a parcouru 99 % de la plongée : l'écran remplit la vue et devient utilisable.
const INTERACTIVE_ZOOM = 0.95
// Au-delà, l'écran grandit vers les bords : le bouton Allumer / Éteindre mordrait dessus.
const CONTROLS_MAX_ZOOM = 0.12

// Section haute à scène collante : le défilement ouvre le capot, plonge dans l'écran et démarre macOS.
export default function MacBookSection() {
  const { locale } = useLocale()
  const text = MACBOOK[locale]
  const lenis = useLenis()
  const sectionRef = useRef<HTMLElement>(null)
  const motion = useRef<MacBookMotion>({ lid: 0, zoom: 0 }).current
  const [isNear, setIsNear] = useState(false)
  const [isVisible, setIsVisible] = useState(false)
  const [phase, setPhase] = useState<MacBookPhase>('closed')
  const [isZoomed, setIsZoomed] = useState(false)
  const [isOverview, setIsOverview] = useState(true)
  const [isShutDown, setIsShutDown] = useState(false)
  const isReducedMotion = useReducedMotion() ?? false
  const { scrollYProgress } = useScroll({ target: sectionRef, offset: ['start start', 'end end'] })

  useEffect(() => {
    const section = sectionRef.current
    if (!section) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsVisible(entry.isIntersecting)
        if (entry.isIntersecting) setIsNear(true)
      },
      { rootMargin: '200px 0px' },
    )
    observer.observe(section)
    return () => observer.disconnect()
  }, [])

  const applyProgress = useCallback(
    (progress: number) => {
      const pose = macBookPoseAt(progress)
      motion.lid = pose.lid
      motion.zoom = pose.zoom
      setPhase(pose.lid === 0 ? 'closed' : pose.lid < 1 ? 'opening' : 'open')
      setIsZoomed(pose.zoom >= INTERACTIVE_ZOOM)
      setIsOverview(pose.zoom <= CONTROLS_MAX_ZOOM)
      // Capot refermé : le prochain passage rallume le Mac.
      if (pose.lid === 0) setIsShutDown(false)
    },
    [motion],
  )

  useEffect(() => applyProgress(scrollYProgress.get()), [applyProgress, scrollYProgress])
  useMotionValueEvent(scrollYProgress, 'change', applyProgress)

  // Clic sur le MacBook : défile jusqu'au plein écran au lieu de l'animer à part.
  const scrollToScreen = useCallback(() => {
    const section = sectionRef.current
    if (!section) return
    const sectionTop = section.getBoundingClientRect().top + window.scrollY
    const top = scrollTopFor(ZOOM_RANGE[1], sectionTop, section.offsetHeight - window.innerHeight)
    if (lenis) lenis.scrollTo(top, { duration: isReducedMotion ? 0 : 2.2 })
    else window.scrollTo({ top, behavior: isReducedMotion ? 'auto' : 'smooth' })
  }, [lenis, isReducedMotion])

  const isPoweredOn = phase === 'open' && !isShutDown

  return (
    <section ref={sectionRef} aria-label={text.sectionLabel} className="relative h-[400svh] bg-black">
      <div className="sticky top-0 h-svh overflow-hidden">
        {isNear && (
          <Canvas
            flat
            frameloop={isVisible ? 'always' : 'never'}
            dpr={[1, 2]}
            camera={{ fov: 30, near: 1, far: 2000, position: [0, 50, 50] }}
          >
            <MacBookScene
              motion={motion}
              phase={phase}
              isZoomed={isZoomed}
              isPoweredOn={isPoweredOn}
              isShutDown={isShutDown && isZoomed}
              isReducedMotion={isReducedMotion}
              onOpen={scrollToScreen}
              onZoomIn={scrollToScreen}
              onShutDown={() => setIsShutDown(true)}
            />
          </Canvas>
        )}
        {phase === 'closed' && (
          <>
            <p
              aria-hidden
              className="pointer-events-none absolute bottom-[10%] left-1/2 flex -translate-x-1/2 animate-pulse items-center gap-2 rounded-full bg-black/80 px-4 py-2 text-sm text-white motion-reduce:animate-none"
            >
              <MouseIcon className="size-4" />
              {text.openHint}
            </p>
            <Button
              className="sr-only focus-visible:not-sr-only focus-visible:absolute focus-visible:bottom-[6%] focus-visible:left-1/2 focus-visible:h-9 focus-visible:-translate-x-1/2 focus-visible:rounded-full focus-visible:bg-white focus-visible:px-4 focus-visible:text-black"
              onClick={scrollToScreen}
            >
              {text.openLabel}
            </Button>
          </>
        )}
        {phase === 'open' && (isOverview || (isShutDown && isZoomed)) && (
          <MacBookControls isPoweredOn={isPoweredOn} onTogglePower={() => setIsShutDown((current) => !current)} />
        )}
      </div>
    </section>
  )
}

import { useCallback, useEffect, useRef } from 'react'
import { useThree } from '@react-three/fiber'
import { Html } from '@react-three/drei'
import { useContextBridge } from 'its-fine'
import MacOS from '@/components/pages/Home/MacOS/MacOS'
import { coverBox } from '@/logic/cameraFit/cameraFit'
import { canScrollBy } from '@/logic/scrollCapture/scrollCapture'

type ScreenDisplayProps = {
  isPoweredOn: boolean
  isInteractive: boolean
  isFitted: boolean
  onShutDown: () => void
}

const SCREEN_WIDTH_PX = 1512
const SCREEN_HEIGHT_PX = 982
const SCREEN_WIDTH_M = 0.3036
// Chrome rastérise un calque en perspective 3D à sa taille CSS puis l'étire : on le dessine 2 fois plus grand
// et on le réduit d'autant, sinon le texte de macOS sort flou.
const RESOLUTION = 2
// En mode transform, drei Html fait valoir 1 px CSS distanceFactor / 400 unités du monde.
const DISTANCE_FACTOR = (SCREEN_WIDTH_M / (SCREEN_WIDTH_PX * RESOLUTION)) * 400
// En plein écran, le bureau garde au moins cette largeur logique (Dock et barre de menus entiers), réduit au besoin.
const FITTED_MIN_WIDTH = 1024
const FULL_SCREEN = { width: SCREEN_WIDTH_PX, height: SCREEN_HEIGHT_PX, scale: 1 }

function canAncestorScroll(target: EventTarget | null, boundary: HTMLElement, event: WheelEvent) {
  for (let node = target instanceof Element ? target : null; node && node !== boundary; node = node.parentElement) {
    const style = getComputedStyle(node)
    const canScrollY =
      /(auto|scroll)/.test(style.overflowY) &&
      canScrollBy(
        { offset: node.scrollTop, contentSize: node.scrollHeight, viewportSize: node.clientHeight },
        event.deltaY,
      )
    const canScrollX =
      /(auto|scroll)/.test(style.overflowX) &&
      canScrollBy(
        { offset: node.scrollLeft, contentSize: node.scrollWidth, viewportSize: node.clientWidth },
        event.deltaX,
      )
    if (canScrollY || canScrollX) return true
  }
  return false
}

// Écran du MacBook : le composant MacOS à 1512 × 982 px, collé au plan Screen à l'échelle exacte.
export default function ScreenDisplay({ isPoweredOn, isInteractive, isFitted, onShutDown }: ScreenDisplayProps) {
  const aspect = useThree((state) => state.size.width / state.size.height)
  const box = isFitted
    ? coverBox({ width: SCREEN_WIDTH_PX, height: SCREEN_HEIGHT_PX }, aspect, FITTED_MIN_WIDTH)
    : FULL_SCREEN
  const isInteractiveRef = useRef(isInteractive)
  // drei Html rend dans une racine React à part : sans ce pont, MacOS perdrait la locale du site.
  const ContextBridge = useContextBridge()

  useEffect(() => {
    isInteractiveRef.current = isInteractive
  }, [isInteractive])

  // Ref en callback, car drei Html monte son contenu après nos effets.
  const attachWheelCapture = useCallback((container: HTMLDivElement | null) => {
    if (!container) return
    const handleWheel = (event: WheelEvent) => {
      if (!isInteractiveRef.current) return
      if (canAncestorScroll(event.target, container, event)) event.stopPropagation()
    }
    container.addEventListener('wheel', handleWheel, { passive: false })
    return () => container.removeEventListener('wheel', handleWheel)
  }, [])

  return (
    <Html
      transform
      distanceFactor={DISTANCE_FACTOR}
      position={[0, 0, 0.0005]}
      zIndexRange={[10, 0]}
      pointerEvents={isInteractive ? 'auto' : 'none'}
    >
      <div
        ref={attachWheelCapture}
        data-lenis-prevent
