  shiftMonth,
} from '@/logic/macos/calendar/calendar'

type CalendarProps = { frame: WindowFrameProps }

export type DatedEvent = CalendarEvent & { date: string }

// Copie de l'app Calendrier de frvky.online : mois en grille, jour sélectionné, fiches en bas de fenêtre.
export default function Calendar({ frame }: CalendarProps) {
  const { locale } = useLocale()
  const texts = MACOS[locale].calendar
  const intlLocale = GIANT_SUR[locale].intlLocale
  const [today] = useState(() => new Date())
  const todayKey = dateKey(today)
  const [shown, setShown] = useState({ year: today.getFullYear(), month: today.getMonth() })
  const [selectedKey, setSelectedKey] = useState(todayKey)
  const [openEvent, setOpenEvent] = useState<DatedEvent | null>(null)
  const [isBooking, setIsBooking] = useState(false)

  const eventsByDate = useMemo(() => {
    const byDate = new Map<string, DatedEvent[]>()
    for (const event of texts.events) {
      const date = resolveEventDate(today, event.monthOffset, event.day)
      byDate.set(date, [...(byDate.get(date) ?? []), { ...event, date }])
    }
    return byDate
  }, [texts.events, today])

  const cells = monthCells(shown.year, shown.month, texts.weekStart)
  const selectedEvents = eventsByDate.get(selectedKey) ?? []
  const selectedLabel = keyToDate(selectedKey).toLocaleDateString(intlLocale, {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })

  const selectDay = (key: string) => {
    setSelectedKey(key)
    const date = keyToDate(key)
    if (date.getMonth() !== shown.month || date.getFullYear() !== shown.year) {
      setShown({ year: date.getFullYear(), month: date.getMonth() })
    }
  }

  return (
    <FinderWindow frame={frame} title={MACOS[locale].appNames.calendar}>
      <div className="absolute inset-0 flex flex-col bg-(--macos-app-surface) font-(family-name:--font-macos-app) text-(--macos-app-ink) [&_:is(h1,h2)]:font-(family-name:--font-macos-app) [&_:is(h1,h2)]:tracking-normal">
        <div className="flex shrink-0 items-center justify-between border-b border-(--macos-app-line) px-[16px] py-[12px]">
          <button
            type="button"
            aria-label={texts.previous}
            onClick={() => setShown(shiftMonth(shown.year, shown.month, -1))}
            className="cursor-pointer p-[4px] text-(--macos-calendar-red)"
          >
            <ChevronLeft strokeWidth={2.2} className="size-[22px]" />
          </button>
          <h1 className="text-[17px] leading-[25.5px] font-semibold">
            <span className="capitalize">{texts.monthNames[shown.month]}</span> {shown.year}
          </h1>
          <button
            type="button"
            aria-label={texts.next}
            onClick={() => setShown(shiftMonth(shown.year, shown.month, 1))}
            className="cursor-pointer p-[4px] text-(--macos-calendar-red)"
          >
            <ChevronRight strokeWidth={2.2} className="size-[22px]" />
          </button>
        </div>
        <div className="grid grid-cols-7 border-b border-(--macos-app-line) px-[8px] pt-[8px] text-center text-[11px] leading-[16.5px] font-medium text-(--macos-app-faint)">
          {texts.weekdays.map((weekday, index) => (
            <div key={index}>{weekday}</div>
          ))}
        </div>
        <div className="grid shrink-0 grid-cols-7 gap-y-[4px] p-[8px]">
          {cells.map((cell) => {
            const isToday = cell.key === todayKey
            const isSelected = cell.key === selectedKey
            const dots = (eventsByDate.get(cell.key) ?? []).slice(0, 3)
            return (
              <button
                key={cell.key}
                type="button"
                onClick={() => selectDay(cell.key)}
                className="flex cursor-pointer flex-col items-center gap-[2px] py-[4px]"
              >
                <span
                  className={cn(
                    'flex size-[28px] items-center justify-center rounded-full text-[14px] leading-[21px]',
                    isToday
                      ? 'bg-(--macos-calendar-red) font-semibold text-(--macos-app-surface)'
                      : isSelected
                        ? 'border border-(--macos-calendar-red-ring) text-(--macos-app-ink)'
                        : cell.isInMonth
                          ? 'text-(--macos-app-ink)'
                          : 'text-(--macos-app-disabled)',
                  )}
                >
                  {cell.day}
                </span>
                <div className="flex h-[6px] gap-[2px]">
                  {dots.map((event) => (
                    <span key={event.id} className={cn('size-[6px] rounded-full', EVENT_DOT_CLASSES[event.kind])} />
                  ))}
                </div>
              </button>
            )
          })}
        </div>
        <div className="flex items-center justify-between border-t border-(--macos-app-line) px-[16px] py-[8px]">
          <span className="text-[13px] leading-[19.5px] font-semibold text-(--macos-app-muted)">{selectedLabel}</span>
          <button
            type="button"
            onClick={() => setIsBooking(true)}
            className="cursor-pointer rounded-full bg-(--macos-calendar-red) px-[12px] py-[4px] text-[13px] leading-[19.5px] font-semibold text-(--macos-app-surface)"
          >
            {texts.bookMeeting}
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-auto px-[16px] pb-[16px]">
          {selectedEvents.length === 0 ? (
            <div className="flex h-full items-center justify-center text-[14px] text-(--macos-app-faint)">
              {texts.noEvents}
            </div>
          ) : (
            <div className="space-y-[8px] pt-[4px]">
              {selectedEvents.map((event) => (
                <button
                  key={event.id}
                  type="button"
                  onClick={() => setOpenEvent(event)}
                  className="flex w-full cursor-pointer items-start gap-[10px] rounded-[8px] bg-(--macos-app-card) p-[10px] text-left"
                >
                  <span className={cn('mt-[2px] h-full w-[4px] shrink-0 rounded-full', EVENT_DOT_CLASSES[event.kind])} />
                  <div>
                    <div className="text-[14px] font-medium text-(--macos-app-ink)">{event.name}</div>
                    <div className="text-[12px] text-(--macos-app-muted)">
                      {eventTimeRange(event, texts.isHour12, texts.nextDay)}
                    </div>
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
        {openEvent && (
          <CalendarEventSheet event={openEvent} todayKey={todayKey} onClose={() => setOpenEvent(null)} />
        )}
        {isBooking && (
          <CalendarBookingSheet
            initialDate={selectedKey < todayKey ? todayKey : selectedKey}
            todayKey={todayKey}
            onClose={() => setIsBooking(false)}
          />
        )}
      </div>
    </FinderWindow>
  )
}

import { useState } from 'react'
import { Check } from 'lucide-react'
import BookingField from '@/components/pages/Home/MacOS/Calendar/BookingField'
import { GIANT_SUR } from '@/data/giantSur'
import { MACOS, type MeetingFormat } from '@/data/macos'
import { sendContactMessage } from '@/lib/api/contact'
import { useLocale } from '@/lib/LocaleProvider'
import { cn } from '@/lib/utils'
import { composeMeetingMessage, formatClock, keyToDate, meetingSlots } from '@/logic/macos/calendar/calendar'

type CalendarBookingSheetProps = { initialDate: string; todayKey: string; onClose: () => void }

const FORMATS: MeetingFormat[] = ['video', 'phone', 'inPerson']
const SLOTS = meetingSlots()
const INPUT =
  'min-w-0 flex-1 bg-transparent py-[10px] text-[15px] text-(--macos-app-ink) select-text placeholder:text-(--macos-app-faint) focus:outline-none'
const GROUP = 'overflow-hidden rounded-[12px] bg-(--macos-app-surface)'
const HEADER_BUTTON = 'cursor-pointer text-[16px] text-(--macos-calendar-red)'

export default function CalendarBookingSheet({ initialDate, todayKey, onClose }: CalendarBookingSheetProps) {
  const { locale } = useLocale()
  const calendar = MACOS[locale].calendar
  const texts = calendar.booking
  const [date, setDate] = useState(initialDate)
  const [time, setTime] = useState('12:00')
  const [format, setFormat] = useState<MeetingFormat>('video')
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [phone, setPhone] = useState('')
  const [topic, setTopic] = useState('')
  const [message, setMessage] = useState('')
  const [isSending, setIsSending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isSent, setIsSent] = useState(false)
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'Africa/Porto-Novo'

  const send = async () => {
    setIsSending(true)
    setError(null)
    try {
      const body = composeMeetingMessage(
        { name, email, phone, topic, message, date, time, timezone, format },
        { ...texts, topic: texts.about },
      )
      await sendContactMessage(email, `${texts.title}\n\n${body}`)
      setIsSent(true)
    } catch {
      setError(texts.error)
    } finally {
      setIsSending(false)
    }
  }

  const shortDate = keyToDate(date).toLocaleDateString(GIANT_SUR[locale].intlLocale, {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  })

  return (
    <div className="absolute inset-0 z-30 flex cursor-pointer items-end bg-(--macos-app-scrim)" onClick={onClose}>
      <div
        onClick={(event) => event.stopPropagation()}
        className="flex max-h-[94%] w-full cursor-default flex-col rounded-t-[16px] bg-(--macos-calendar-sheet) shadow-(--macos-app-sheet-shadow)"
      >
        <div className="flex shrink-0 items-center justify-between px-[16px] pt-[12px] pb-[8px]">
          <button type="button" onClick={onClose} className={HEADER_BUTTON}>
            {isSent ? texts.done : texts.cancel}
          </button>
          <span className="text-[16px] font-semibold text-(--macos-app-ink)">{texts.title}</span>
          {isSent ? (
            <span className="w-[48px]" />
          ) : (
            <button
              type="button"
              onClick={send}
              disabled={isSending}
              className={cn(HEADER_BUTTON, 'font-semibold disabled:cursor-default disabled:opacity-40')}
            >
              {isSending ? texts.sending : texts.send}
            </button>
          )}
        </div>
        {isSent ? (
          <div className="px-[24px] pt-[40px] pb-[48px] text-center">
            <div className="mx-auto flex size-[56px] items-center justify-center rounded-full bg-(--macos-calendar-red) text-(--macos-app-surface)">
              <Check strokeWidth={2.6} className="size-[28px]" />
            </div>
            <p className="mt-[16px] text-[19px] font-semibold text-(--macos-app-ink)">{texts.sentTitle}</p>
            <p className="mt-[4px] text-[14px] leading-relaxed text-(--macos-app-muted)">
              {texts.sentBody.replace('{date}', shortDate).replace('{time}', formatClock(time, calendar.isHour12))}
            </p>
          </div>
        ) : (
          <div className="min-h-0 flex-1 space-y-[20px] overflow-auto px-[16px] pt-[4px] pb-[40px]">
            <div className={GROUP}>
              <BookingField label={texts.name}>
                <input
                  value={name}
                  onChange={(event) => setName(event.target.value.slice(0, 100))}
                  placeholder={texts.namePlaceholder}
                  className={INPUT}
                />
              </BookingField>
              <BookingField label={texts.email}>
                <input
                  value={email}
                  onChange={(event) => setEmail(event.target.value.slice(0, 254))}
                  placeholder={texts.emailPlaceholder}
                  type="email"
                  inputMode="email"
                  className={INPUT}
                />
              </BookingField>
            </div>
            <div className={GROUP}>
              <BookingField label={texts.date}>
                <input
                  type="date"
                  value={date}
                  min={todayKey}
                  onChange={(event) => setDate(event.target.value)}
                  className={cn(INPUT, 'text-right')}
                />
              </BookingField>
              <BookingField label={texts.time}>
                <select
                  value={time}
                  onChange={(event) => setTime(event.target.value)}
                  className={cn(INPUT, 'cursor-pointer text-right')}
                >
                  {SLOTS.map((slot) => (
                    <option key={slot} value={slot}>
                      {formatClock(slot, calendar.isHour12)}
                    </option>
                  ))}
                </select>
              </BookingField>
              <p className="px-[16px] pb-[10px] text-[12px] text-(--macos-app-faint)">
                {texts.timezoneHint.replace('{timezone}', timezone.replace(/_/g, ' '))}
              </p>
            </div>
            <div>
              <div className="flex rounded-[9px] bg-(--macos-calendar-segment) p-[2px]">
                {FORMATS.map((item) => (
                  <button
                    key={item}
                    type="button"
                    onClick={() => setFormat(item)}
                    className={cn(
                      'flex-1 cursor-pointer rounded-[7px] py-[6px] text-[13px] font-medium',
                      format === item
                        ? 'bg-(--macos-app-surface) text-(--macos-app-ink) shadow-(--macos-calendar-segment-shadow)'
                        : 'text-(--macos-app-secondary)',
                    )}
                  >
                    {texts.formats[item]}
                  </button>
                ))}
              </div>
              {format === 'phone' && (
                <div className={cn(GROUP, 'mt-[12px]')}>
                  <BookingField label={texts.phone}>
                    <input
                      value={phone}
                      onChange={(event) => setPhone(event.target.value.slice(0, 30))}
                      placeholder={texts.phonePlaceholder}
                      type="tel"
                      inputMode="tel"
                      className={INPUT}
                    />
                  </BookingField>
                </div>
              )}
              {format === 'inPerson' && (
                <p className="mt-[8px] px-[4px] text-[12px] text-(--macos-app-muted)">{texts.inPersonHint}</p>
              )}
            </div>
            <div className={GROUP}>
              <BookingField label={texts.about}>
                <input
                  value={topic}
                  onChange={(event) => setTopic(event.target.value.slice(0, 120))}
                  placeholder={texts.aboutPlaceholder}
                  className={INPUT}
                />
              </BookingField>
              <textarea
                value={message}
                onChange={(event) => setMessage(event.target.value.slice(0, 4000))}
                placeholder={texts.messagePlaceholder}
                rows={5}
                className="w-full resize-none border-t border-(--macos-app-line) bg-transparent px-[16px] py-[12px] text-[15px] text-(--macos-app-ink) select-text placeholder:text-(--macos-app-faint) focus:outline-none"
              />
            </div>
            {error && <p className="px-[4px] text-[13px] text-(--macos-calendar-error)">{error}</p>}
            <p className="px-[4px] text-[12px] leading-relaxed text-(--macos-app-faint)">{texts.footnote}</p>
          </div>
        )}
      </div>
    </div>
  )
}

import type { CalendarEventKind } from '@/data/macos'

export const EVENT_DOT_CLASSES: Record<CalendarEventKind, string> = {
  release: 'bg-(--macos-calendar-dot-release)',
  meeting: 'bg-(--macos-calendar-dot-meeting)',
  other: 'bg-(--macos-calendar-dot-other)',
}

import { useEffect, useRef } from 'react'
import { motion } from 'framer-motion'
import { Bluetooth, Moon, Radio, Sun, SunMoon, Volume2, Wifi } from 'lucide-react'
import ControlCenterSlider from '@/components/pages/Home/MacOS/ControlCenterSlider'
import ControlCenterToggle from '@/components/pages/Home/MacOS/ControlCenterToggle'
import { MACOS } from '@/data/macos'
import { useLocale } from '@/lib/LocaleProvider'
import type { MacDisplay } from '@/lib/macDisplaySession'

export type ControlCenterSettings = {
  isWifiOn: boolean
  isBluetoothOn: boolean
  isAirDropOn: boolean
  isFocusOn: boolean
  volume: number
}

type ControlCenterProps = {
  display: MacDisplay
  settings: ControlCenterSettings
  onDisplayChange: (display: MacDisplay) => void
  onSettingsChange: (settings: ControlCenterSettings) => void
  onClose: () => void
}

const TILE = 'rounded-[14px] bg-(--macos-cc-tile) p-[10px]'

// Centre de contrôle Sequoia : panneau en verre ancré sous son icône, en haut à droite de la barre de menus.
export default function ControlCenter({
  display,
  settings,
  onDisplayChange,
  onSettingsChange,
  onClose,
}: ControlCenterProps) {
  const { locale } = useLocale()
  const texts = MACOS[locale].controlCenter
  const panelRef = useRef<HTMLDivElement>(null)
  const status = (isOn: boolean, onLabel = texts.on) => (isOn ? onLabel : texts.off)
  const toggle = (key: Exclude<keyof ControlCenterSettings, 'volume'>) =>
    onSettingsChange({ ...settings, [key]: !settings[key] })

  useEffect(() => {
    const closeOutside = (event: PointerEvent) => {
      const target = event.target as Element | null
      if (panelRef.current?.contains(target) || target?.closest('[data-control-center-toggle]')) return
      onClose()
    }
    const closeOnEscape = (event: KeyboardEvent) => event.key === 'Escape' && onClose()
    document.addEventListener('pointerdown', closeOutside, true)
    document.addEventListener('keydown', closeOnEscape)
    return () => {
      document.removeEventListener('pointerdown', closeOutside, true)
      document.removeEventListener('keydown', closeOnEscape)
    }
  }, [onClose])

  return (
    <motion.div
      ref={panelRef}
      role="dialog"
      aria-label={texts.label}
      initial={{ opacity: 0, scale: 0.9, y: -8 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.95, y: -4, transition: { duration: 0.14, ease: 'easeIn' } }}
      transition={{ type: 'spring', stiffness: 520, damping: 34, mass: 0.8 }}
      style={{ transformOrigin: '100% 0%' }}
      className="absolute top-[36px] right-[8px] z-50 flex w-[320px] flex-col gap-[10px] rounded-[20px] border border-(--macos-cc-border) bg-(--macos-cc-glass) p-[10px] font-sans text-[13px] text-(--macos-cc-text) shadow-(--macos-cc-shadow) backdrop-blur-2xl backdrop-saturate-[1.8]"
    >
      <div className="grid grid-cols-2 gap-[10px]">
        <div className={`${TILE} flex flex-col gap-[10px]`}>
          <ControlCenterToggle
            icon={Wifi}
            label={texts.wifi}
            status={status(settings.isWifiOn, texts.wifiOn)}
            isOn={settings.isWifiOn}
            onToggle={() => toggle('isWifiOn')}
          />
          <ControlCenterToggle
            icon={Bluetooth}
            label={texts.bluetooth}
            status={status(settings.isBluetoothOn)}
            isOn={settings.isBluetoothOn}
            onToggle={() => toggle('isBluetoothOn')}
          />
          <ControlCenterToggle
            icon={Radio}
            label={texts.airDrop}
            status={status(settings.isAirDropOn, texts.airDropOn)}
            isOn={settings.isAirDropOn}
            onToggle={() => toggle('isAirDropOn')}
          />
        </div>
        <div className="flex flex-col gap-[10px]">
          <div className={`${TILE} flex flex-1 items-center`}>
            <ControlCenterToggle
              icon={Moon}
              label={texts.focus}
              status={settings.isFocusOn ? texts.focusOn : undefined}
              isOn={settings.isFocusOn}
              onToggle={() => toggle('isFocusOn')}
            />
          </div>
          <div className={`${TILE} flex flex-1 items-center`}>
            <ControlCenterToggle
              icon={SunMoon}
              label={texts.darkMode}
              status={status(display.isDarkMode)}
              isOn={display.isDarkMode}
              onToggle={() => onDisplayChange({ ...display, isDarkMode: !display.isDarkMode })}
            />
          </div>
        </div>
      </div>
      <ControlCenterSlider
        icon={Sun}
        label={texts.display}
        value={display.brightness}
        onChange={(brightness) => onDisplayChange({ ...display, brightness })}
      />
      <ControlCenterSlider
        icon={Volume2}
        label={texts.sound}
        value={settings.volume}
        onChange={(volume) => onSettingsChange({ ...settings, volume })}
      />
    </motion.div>
  )
}

import type { LucideIcon } from 'lucide-react'

type ControlCenterSliderProps = {
  icon: LucideIcon
  label: string
  value: number
  onChange: (value: number) => void
}

// Curseur maison sur un <input type="range"> natif invisible : le Slider de shadcn calcule la position du pointeur
// avec getBoundingClientRect, faussé quand le bureau est affiché en CSS 3D sur le MacBook.
export default function ControlCenterSlider({ icon: Icon, label, value, onChange }: ControlCenterSliderProps) {
  const percent = Math.round(value * 100)

  return (
    <div className="flex flex-col gap-[7px] rounded-[14px] bg-(--macos-cc-tile) px-[12px] pt-[9px] pb-[11px]">
      <p className="text-[12px] font-semibold">{label}</p>
      <div className="relative h-[22px] overflow-hidden rounded-full bg-(--macos-cc-track)">
        <div className="absolute inset-y-0 left-0 rounded-full bg-(--macos-cc-fill)" style={{ width: `max(22px, ${percent}%)` }} />
        <Icon
          aria-hidden="true"
          strokeWidth={2.2}
          className="pointer-events-none absolute top-1/2 left-[5px] size-[13px] -translate-y-1/2 text-(--macos-cc-slider-glyph)"
        />
        <input
          type="range"
          min={0}
          max={100}
          value={percent}
          aria-label={label}
          onChange={(event) => onChange(Number(event.target.value) / 100)}
          className="absolute inset-0 size-full cursor-pointer opacity-0"
        />
      </div>
    </div>
  )
}

