import { useEffect, useRef, useState, type PointerEvent } from 'react'
import { Heart, Info, Share, SlidersHorizontal, Trash2 } from 'lucide-react'
import PhotoActionButton from '@/components/pages/Home/MacOS/Photos/PhotoActionButton'
import PhotoInfoSheet from '@/components/pages/Home/MacOS/Photos/PhotoInfoSheet'
import type { PhotoItem } from '@/components/pages/Home/MacOS/Photos/Photos'
import { MACOS } from '@/data/macos'
import { useLocale } from '@/lib/LocaleProvider'
import { cn } from '@/lib/utils'
import { swipeGesture } from '@/logic/macos/photoAlbums/photoAlbums'
import { unsplashPhotoUrl } from '@/logic/unsplashPhotoUrl/unsplashPhotoUrl'

type PhotoViewerProps = {
  items: PhotoItem[]
  index: number
  onNavigate: (index: number) => void
  onClose: () => void
}

const ACTION_ICON = 'size-[23px]'

// Visionneuse plein cadre : pellicule, flèches du clavier, glisser pour changer de photo.
export default function PhotoViewer({ items, index, onNavigate, onClose }: PhotoViewerProps) {
  const { locale } = useLocale()
  const texts = MACOS[locale].photos
  const item = items[index]
  const hasPrevious = index > 0
  const hasNext = index < items.length - 1
  const pointerStart = useRef<{ x: number; y: number } | null>(null)
  const filmstrip = useRef<HTMLDivElement>(null)
  const [loadedId, setLoadedId] = useState<string | null>(null)
  const [likedIds, setLikedIds] = useState<string[]>([])
  const [isInfoOpen, setIsInfoOpen] = useState(false)
  const isLoaded = loadedId === item.id
  const isLiked = likedIds.includes(item.id)

  useEffect(() => {
    const strip = filmstrip.current
    const thumb = strip?.querySelector<HTMLElement>(`[data-filmstrip-index="${index}"]`)
    if (!strip || !thumb) return
    strip.scrollTo({ left: thumb.offsetLeft - strip.clientWidth / 2 + thumb.offsetWidth / 2, behavior: 'smooth' })
  }, [index])

  useEffect(() => {
    const handleKey = (event: KeyboardEvent) => {
      if (event.key === 'ArrowLeft' && hasPrevious) onNavigate(index - 1)
      else if (event.key === 'ArrowRight' && hasNext) onNavigate(index + 1)
      else if (event.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [index, hasPrevious, hasNext, onNavigate, onClose])

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const start = pointerStart.current
    pointerStart.current = null
    if (!start) return
    const gesture = swipeGesture(event.clientX - start.x, event.clientY - start.y)
    if (gesture === 'next' && hasNext) onNavigate(index + 1)
    if (gesture === 'previous' && hasPrevious) onNavigate(index - 1)
  }

  const share = async () => {
    const url = unsplashPhotoUrl(item.photoId, 1600)
    try {
      if (navigator.share) await navigator.share({ url, title: item.fileName })
      else await navigator.clipboard.writeText(url)
    } catch {
      // Partage annulé par le visiteur.
    }
  }

  return (
    <div
      onClick={onClose}
      onPointerDown={(event) => (pointerStart.current = { x: event.clientX, y: event.clientY })}
      onPointerUp={handlePointerUp}
      className="absolute inset-0 z-[999] flex touch-none cursor-pointer flex-col bg-(--macos-photos-bg)"
    >
      <button
        type="button"
        onClick={onClose}
        aria-label={texts.close}
        className="absolute top-[16px] right-[16px] z-10 cursor-pointer rounded-full bg-(--macos-photos-button) px-[12px] py-[4px] text-[14px] text-(--macos-photos-text) hover:bg-(--macos-photos-button-hover)"
      >
        {texts.done}
      </button>
      <div
        onClick={(event) => event.stopPropagation()}
        className="relative flex min-h-0 flex-1 cursor-default items-center justify-center overflow-hidden"
      >
        <img
          key={item.id}
          src={unsplashPhotoUrl(item.photoId, 1600)}
          alt={item.alt}
          draggable={false}
          onLoad={() => setLoadedId(item.id)}
          className={cn(
            'size-full object-contain transition-all duration-700',
            isLoaded ? 'blur-0 scale-100' : 'scale-105 blur-xl',
          )}
        />
      </div>
      <div
        onClick={(event) => event.stopPropagation()}
        className="z-10 shrink-0 cursor-default bg-linear-to-t from-(--macos-photos-bg) to-(--macos-photos-shade-soft)"
      >
        {items.length > 1 && (
          <div
            ref={filmstrip}
            className="flex touch-pan-x gap-[4px] overflow-x-auto px-[12px] py-[8px] [scrollbar-width:none]"
          >
            {items.map((thumb, thumbIndex) => (
              <button
                key={thumb.id}
                type="button"
                data-filmstrip-index={thumbIndex}
                onClick={() => onNavigate(thumbIndex)}
                className={cn(
                  'size-[44px] shrink-0 cursor-pointer overflow-hidden rounded-[6px] transition',
                  thumbIndex === index ? 'opacity-100 ring-2 ring-(--macos-photos-text)' : 'opacity-50',
                )}
              >
                <img
                  src={unsplashPhotoUrl(thumb.photoId, 120)}
                  alt=""
                  draggable={false}
                  className="size-full object-cover"
                />
              </button>
            ))}
          </div>
        )}
        <div className="flex items-center justify-around px-[8px] pt-[4px] pb-[24px]">
          <PhotoActionButton label={texts.share} onClick={share}>
            <Share strokeWidth={1.8} className={ACTION_ICON} />
          </PhotoActionButton>
          <PhotoActionButton
            label={texts.like}
            onClick={() =>
              setLikedIds((current) => (isLiked ? current.filter((id) => id !== item.id) : [...current, item.id]))
            }
          >
            <Heart
              strokeWidth={1.8}
              className={cn(ACTION_ICON, isLiked && 'fill-(--macos-photos-like) text-(--macos-photos-like)')}
            />
          </PhotoActionButton>
          <PhotoActionButton label={texts.info} onClick={() => setIsInfoOpen((isOpen) => !isOpen)}>
            <Info strokeWidth={1.8} className={ACTION_ICON} />
          </PhotoActionButton>
          <PhotoActionButton label={texts.adjustments} onClick={() => {}}>
            <SlidersHorizontal strokeWidth={1.8} className={ACTION_ICON} />
          </PhotoActionButton>
          <PhotoActionButton label={texts.delete} onClick={() => {}}>
            <Trash2 strokeWidth={1.8} className={ACTION_ICON} />
          </PhotoActionButton>
        </div>
      </div>
      {isInfoOpen && (
        <div onClick={(event) => event.stopPropagation()} className="contents">
          <PhotoInfoSheet item={item} onClose={() => setIsInfoOpen(false)} />
        </div>
      )}
    </div>
  )
}

import { useMemo, useState } from 'react'
import { ChevronLeft, Image, LayoutGrid } from 'lucide-react'
import FinderWindow from '@/components/pages/Home/MacOS/FinderWindow'
import PhotosAlbumCard from '@/components/pages/Home/MacOS/Photos/PhotosAlbumCard'
import PhotosGrid from '@/components/pages/Home/MacOS/Photos/PhotosGrid'
import PhotosMemoryCard from '@/components/pages/Home/MacOS/Photos/PhotosMemoryCard'
import PhotosTab from '@/components/pages/Home/MacOS/Photos/PhotosTab'
import PhotoViewer from '@/components/pages/Home/MacOS/Photos/PhotoViewer'
import { useMacFiles } from '@/components/pages/Home/MacOS/useMacFiles'
import type { WindowFrameProps } from '@/components/pages/Home/MacOS/Window'
import { MACOS } from '@/data/macos'
import { PROJECTS } from '@/data/projects'
import { useLocale } from '@/lib/LocaleProvider'
import { collectImages, findNode } from '@/logic/macos/fileTree/fileTree'
import { groupByAlbum } from '@/logic/macos/photoAlbums/photoAlbums'

type PhotosProps = { frame: WindowFrameProps }

export type PhotoItem = { id: string; photoId: string; alt: string; album: string; fileName: string }

type OpenAlbum = { label: string; items: PhotoItem[] }

const SECTION_HEADING = 'mb-[8px] px-[4px] text-[13px] leading-normal font-semibold tracking-wide text-(--macos-photos-text-50) uppercase'

// Copie de l'app Photos de frvky.online : Photothèque, Albums (Souvenirs, Épinglés) et visionneuse.
export default function Photos({ frame }: PhotosProps) {
  const { locale } = useLocale()
  const texts = MACOS[locale].photos
  const root = useMacFiles()
  const [tab, setTab] = useState<'library' | 'albums'>('library')
  const [openAlbum, setOpenAlbum] = useState<OpenAlbum | null>(null)
  const [viewer, setViewer] = useState<{ items: PhotoItem[]; index: number } | null>(null)

  const library = useMemo((): PhotoItem[] => {
    const projectPhotos = PROJECTS[locale].flatMap((project) =>
      project.photos.map((photo, index) => ({
        id: `${project.name}-${photo.id}`,
        photoId: photo.id,
        alt: photo.alt,
        album: project.name,
        fileName: `${project.name.toLowerCase()}-${index + 1}.jpg`,
      })),
    )
    const finderPhotos = collectImages(root).map(({ path, node }) => ({
      id: path.join('/'),
      photoId: node.photoId,
      alt: node.alt,
      album: findNode(root, path.slice(0, -1))?.name ?? texts.library,
      fileName: node.name,
    }))
    // Les images du Finder reprennent souvent celles des projets : une seule entrée par photo.
    const finderOnly = finderPhotos.filter((photo) => !projectPhotos.some((item) => item.photoId === photo.photoId))
    return [...projectPhotos, ...finderOnly]
  }, [locale, root, texts.library])

  const albums = useMemo(() => groupByAlbum(library), [library])
  const memories = albums.filter(([album]) => texts.memoriesAlbums.includes(album))
  const pinned = albums.filter(([album]) => texts.pinnedAlbums.includes(album))
  const gridItems = openAlbum ? openAlbum.items : library
  const openViewer = (index: number) => setViewer({ items: gridItems, index })

  return (
    <FinderWindow frame={frame} title={MACOS[locale].appNames.photos}>
      <div className="absolute inset-0 flex flex-col bg-(--macos-photos-bg) font-(family-name:--font-macos-app) text-(--macos-photos-text) [&_:is(h1,h2)]:font-(family-name:--font-macos-app) [&_:is(h1,h2)]:tracking-normal">
        <div className="flex shrink-0 items-center border-b border-(--macos-photos-line) px-[16px] py-[12px]">
          {openAlbum ? (
            <button
              type="button"
              onClick={() => setOpenAlbum(null)}
              className="flex cursor-pointer items-center gap-[4px] text-[15px] font-medium text-(--macos-photos-link)"
            >
              <ChevronLeft strokeWidth={2.2} className="size-[20px]" /> {texts.albums}
            </button>
          ) : (
            <h1 className="text-[20px] leading-[30px] font-bold">{tab === 'library' ? texts.library : texts.albums}</h1>
          )}
        </div>
        <div className="min-h-0 flex-1 overflow-auto p-[12px]">
          {openAlbum || tab === 'library' ? (
            <PhotosGrid items={gridItems} emptyLabel={texts.empty} onSelect={openViewer} />
          ) : (
            <div className="space-y-[24px]">
              {memories.length > 0 && (
                <section>
                  <h2 className={SECTION_HEADING}>{texts.memories}</h2>
                  <div className="-mx-[12px] flex gap-[12px] overflow-x-auto px-[12px] pb-[4px] [scrollbar-width:none]">
                    {memories.map(([album, items]) => (
                      <PhotosMemoryCard
                        key={album}
                        album={album}
                        items={items}
                        countLabel={items.length === 1 ? texts.item : texts.items}
                        onOpen={() => setViewer({ items, index: 0 })}
                      />
                    ))}
                  </div>
                </section>
              )}
              {pinned.length > 0 && (
                <section>
                  <h2 className={SECTION_HEADING}>{texts.pinned}</h2>
                  <div className="grid grid-cols-2 gap-[16px]">
                    {pinned.map(([album, items]) => (
                      <PhotosAlbumCard
                        key={album}
                        label={album}
                        items={items}
                        onOpen={() => setOpenAlbum({ label: album, items })}
                      />
                    ))}
                  </div>
                </section>
              )}
              <section>
                <h2 className={SECTION_HEADING}>{texts.albums}</h2>
                <div className="grid grid-cols-2 gap-[16px]">
                  {albums.map(([album, items]) => (
                    <PhotosAlbumCard
                      key={album}
                      label={album}
                      items={items}
                      onOpen={() => setOpenAlbum({ label: album, items })}
                    />
                  ))}
                </div>
              </section>
              <section>
                <h2 className={SECTION_HEADING}>{texts.peopleAndPets}</h2>
                <p className="px-[4px] text-[13px] text-(--macos-photos-text-40)">{texts.peopleHint}</p>
              </section>
            </div>
          )}
        </div>
        {!openAlbum && (
          <div className="flex shrink-0 justify-around border-t border-(--macos-photos-line) bg-(--macos-photos-bar) py-[8px]">
            <PhotosTab label={texts.library} isActive={tab === 'library'} Icon={Image} onClick={() => setTab('library')} />
            <PhotosTab
              label={texts.albums}
              isActive={tab === 'albums'}
              Icon={LayoutGrid}
              onClick={() => setTab('albums')}
            />
          </div>
        )}
        {viewer && (
          <PhotoViewer
            items={viewer.items}
            index={viewer.index}
            onNavigate={(index) => setViewer({ items: viewer.items, index })}
            onClose={() => setViewer(null)}
          />
        )}
      </div>
    </FinderWindow>
  )
}

