import { useRef, useState, type MouseEvent, type PointerEvent, type ReactNode } from 'react'
import { motion, useReducedMotion } from 'framer-motion'
import TrafficLights from '@/components/pages/Home/MacOS/TrafficLights'
import { useGenie, type GenieDirection } from '@/components/pages/Home/MacOS/useGenie'
import { cn } from '@/lib/utils'
import type { Point } from '@/logic/macos/windowBounds/windowBounds'
import type { MacWindow } from '@/logic/macos/windowManager/windowManager'

export type WindowFrameProps = {
  window: MacWindow
  isFocused: boolean
  onFocus: () => void
  onClose: () => void
  onMinimize: () => void
  onZoom: () => void
  onMove: (position: Point) => void
}

type WindowProps = WindowFrameProps & {
  title: string
  canZoom?: boolean
  toolbar?: ReactNode
  sidebar?: ReactNode
  sidebarClassName?: string
  titleBarClassName?: string
  contentClassName?: string
  className?: string
  children: ReactNode
}

type DragStart = { pointerX: number; pointerY: number; x: number; y: number; scale: number }

const INTERACTIVE = 'button, input, textarea, a, select, [role="tab"]'

const OPEN_TRANSITION = { type: 'spring', stiffness: 380, damping: 32, mass: 0.9 } as const
const FADE_TRANSITION = { duration: 0.2, ease: 'easeOut' } as const
const INSTANT = { duration: 0 } as const

export default function Window({
  window: macWindow,
  title,
  isFocused,
  canZoom = true,
  toolbar,
  sidebar,
  sidebarClassName,
  titleBarClassName,
  contentClassName,
  className,
  children,
  onFocus,
  onClose,
  onMinimize,
  onZoom,
  onMove,
}: WindowProps) {
  const dragStart = useRef<DragStart | null>(null)
  const sectionRef = useRef<HTMLElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const { rect, isMinimized, z } = macWindow
  const isReducedMotion = useReducedMotion() ?? false
  const [wasMinimized, setWasMinimized] = useState(isMinimized)
  const [genieDirection, setGenieDirection] = useState<GenieDirection | null>(
    macWindow.isOpenedFromDock && !isReducedMotion ? 'restore' : null,
  )
  const [hasGenieAtMount] = useState(genieDirection !== null)

  if (wasMinimized !== isMinimized) {
    setWasMinimized(isMinimized)
    // Mouvement réduit : pas de génie, la fenêtre s'efface en fondu court.
    if (!isReducedMotion) setGenieDirection(isMinimized ? 'minimize' : 'restore')
  }

  useGenie(sectionRef, genieDirection, rect, macWindow.app, () => setGenieDirection(null))

  // Pendant le génie, ce sont les bandes copiées qui bougent : la vraie fenêtre reste cachée sur place.
  const isHiddenByGenie = !isReducedMotion && (isMinimized || genieDirection !== null)
  const isFadedOut = isReducedMotion && isMinimized

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || (event.target as HTMLElement).closest(INTERACTIVE)) return
    if (macWindow.isMaximized) return
    // L'écran peut être mis à l'échelle (MacBook 3D) : on ramène le déplacement du pointeur en pixels de l'écran.
    const root = event.currentTarget.closest<HTMLElement>('[data-macos-root]')
    const scale = root ? root.getBoundingClientRect().width / root.offsetWidth || 1 : 1
    dragStart.current = { pointerX: event.clientX, pointerY: event.clientY, x: rect.x, y: rect.y, scale }
    event.currentTarget.setPointerCapture(event.pointerId)
    setIsDragging(true)
  }

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const start = dragStart.current
    if (!start) return
    onMove({
      x: start.x + (event.clientX - start.pointerX) / start.scale,
      y: start.y + (event.clientY - start.pointerY) / start.scale,
    })
  }

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    if (!dragStart.current) return
    dragStart.current = null
    event.currentTarget.releasePointerCapture(event.pointerId)
    setIsDragging(false)
  }

  const dragArea = {
    onPointerDown: handlePointerDown,
    onPointerMove: handlePointerMove,
    onPointerUp: handlePointerUp,
    onPointerCancel: handlePointerUp,
    onDoubleClick: (event: MouseEvent<HTMLDivElement>) => {
      if (canZoom && !(event.target as HTMLElement).closest(INTERACTIVE)) onZoom()
    },
  }
  const lights = (
    <TrafficLights isFocused={isFocused} canZoom={canZoom} onClose={onClose} onMinimize={onMinimize} onZoom={onZoom} />
  )
  const hasToolbar = toolbar !== undefined

  return (
    <motion.section
      ref={sectionRef}
      aria-label={title}
      aria-hidden={isMinimized || undefined}
      onPointerDownCapture={onFocus}
      initial={
        hasGenieAtMount
          ? false
          : { opacity: 0, scaleX: 0.88, scaleY: 0.88, x: rect.x, y: rect.y + 24, width: rect.width, height: rect.height }
      }
      animate={{ opacity: isFadedOut ? 0 : 1, scaleX: 1, scaleY: 1, x: rect.x, y: rect.y, width: rect.width, height: rect.height }}
      exit={{ opacity: 0, scale: 0.92, transition: { duration: 0.18, ease: 'easeIn' } }}
      transition={isDragging || isHiddenByGenie ? INSTANT : isReducedMotion ? FADE_TRANSITION : OPEN_TRANSITION}
      style={{
        zIndex: z,
        pointerEvents: isMinimized || isHiddenByGenie ? 'none' : 'auto',
        visibility: isHiddenByGenie ? 'hidden' : 'visible',
      }}
      className={cn(
        'absolute top-0 left-0 flex overflow-hidden rounded-[10px] border border-(--macos-window-border) font-(family-name:--font-giantsur) text-[13px] text-(--macos-text) backdrop-blur-3xl backdrop-saturate-[1.8] transition-shadow duration-300',
        isFocused ? 'shadow-(--macos-shadow-window)' : 'shadow-(--macos-shadow-window-idle)',
        sidebar ? 'flex-row bg-(--macos-window-glass)' : 'flex-col bg-(--macos-window)',
        className,
      )}
    >
      {sidebar && (
        <aside
          className={cn(
            'flex w-[200px] shrink-0 flex-col border-r border-(--macos-separator-strong) bg-(--macos-window-sidebar)',
            sidebarClassName,
          )}
        >
          <div {...dragArea} className="flex h-[52px] shrink-0 items-center px-[18px]">
            {lights}
          </div>
          <div className="min-h-0 flex-1 overflow-y-auto px-[10px] pb-[12px]">{sidebar}</div>
        </aside>
      )}
      <div className={cn('flex min-w-0 flex-1 flex-col', sidebar && 'bg-(--macos-window)', contentClassName)}>
        <div
          {...dragArea}
          className={cn(
            'relative flex shrink-0 items-center gap-[14px] border-b border-(--macos-separator-strong) bg-(--macos-window-toolbar) px-[14px] transition-opacity duration-200',
            hasToolbar || sidebar ? 'h-[52px]' : 'h-[38px]',
            !isFocused && 'opacity-75',
            titleBarClassName,
          )}
        >
          {!sidebar && lights}
          {toolbar ?? (
            <p
              className={cn(
                'pointer-events-none truncate font-semibold',
                sidebar ? 'text-[15px]' : 'absolute inset-x-[90px] text-center',
                !isFocused && 'text-(--macos-text-muted)',
              )}
            >
              {title}
            </p>
          )}
        </div>
        <div className="relative min-h-0 flex-1">{children}</div>
      </div>
    </motion.section>
  )
}

import type { IconType } from 'react-icons'
import { FaLinkedinIn } from 'react-icons/fa6'
import { SiGithub } from 'react-icons/si'
import type { DockLinkId } from '@/data/giantSur'

// Logos de marque (pas des icônes d'interface) : simple-icons n'a plus LinkedIn, d'où Font Awesome pour celui-ci.
export const DOCK_LINK_LOGOS: Record<DockLinkId, { Logo: IconType; className: string }> = {
  github: { Logo: SiGithub, className: 'text-(--macos-dock-github)' },
  linkedin: { Logo: FaLinkedinIn, className: 'text-(--macos-dock-linkedin)' },
}

import type { Rect } from '@/logic/macos/windowBounds/windowBounds'

const FALLBACK_ICON_SIZE = 48

// Position en pixels de l'écran macOS (offsets de mise en page, insensibles à la 3D du MacBook).
function offsetWithin(element: HTMLElement, root: HTMLElement) {
  let x = 0
  let y = 0
  for (let node: HTMLElement | null = element; node && node !== root; node = node.offsetParent as HTMLElement | null) {
    x += node.offsetLeft
    y += node.offsetTop
  }
  return { x, y }
}

// Icône du Dock de l'app ; une app absente du Dock vise le bout droit du Dock, là où macOS range les fenêtres réduites.
export function dockTargetRect(root: HTMLElement, app: string): Rect | null {
  const icon = root.querySelector<HTMLElement>(`[data-dock-app="${app}"] img`)
  if (icon) return { ...offsetWithin(icon, root), width: icon.offsetWidth, height: icon.offsetHeight }
  const dock = root.querySelector<HTMLElement>('[data-dock]')
  if (!dock) return null
  const { x, y } = offsetWithin(dock, root)
  return {
    x: x + dock.offsetWidth - FALLBACK_ICON_SIZE - 8,
    y: y + (dock.offsetHeight - FALLBACK_ICON_SIZE) / 2,
    width: FALLBACK_ICON_SIZE,
    height: FALLBACK_ICON_SIZE,
  }
}

import { useEffect, useLayoutEffect, useRef, type RefObject } from 'react'
import { dockTargetRect } from '@/components/pages/Home/MacOS/dockTarget'
import { genieOpacity, genieStripCount, genieStrips } from '@/logic/macos/genie/genie'
import type { Rect } from '@/logic/macos/windowBounds/windowBounds'

export type GenieDirection = 'minimize' | 'restore'

type GenieRun = { layer: HTMLDivElement; strips: HTMLDivElement[]; window: Rect; icon: Rect; progress: number; frame: number }

const DURATION_MS = 520

// La fenêtre est copiée en bandes horizontales empilées : chaque bande est translatée et étirée seule, ce qui tord la forme.
function buildLayer(source: HTMLElement, root: HTMLElement, window: Rect, icon: Rect): GenieRun {
  const layer = document.createElement('div')
  layer.setAttribute('aria-hidden', 'true')
  layer.inert = true
  layer.className = 'pointer-events-none absolute inset-0 z-20'
  const count = genieStripCount(window.height)
  const stripHeight = window.height / count
  const scrolled = Array.from(source.querySelectorAll<HTMLElement>('*'))
    .map((element, index) => ({ index, top: element.scrollTop, left: element.scrollLeft }))
    .filter((entry) => entry.top > 0 || entry.left > 0)

  const strips = Array.from({ length: count }, (_, index) => {
    const strip = document.createElement('div')
    strip.style.cssText = `position:absolute;left:0;top:0;width:${window.width}px;height:${stripHeight + 1}px;overflow:hidden;transform-origin:0 0;will-change:transform`
    const clone = source.cloneNode(true) as HTMLElement
    clone.style.transform = 'none'
    clone.style.left = '0'
    clone.style.top = `${-index * stripHeight}px`
    clone.style.width = `${window.width}px`
    clone.style.height = `${window.height}px`
    clone.style.opacity = '1'
    clone.style.visibility = 'visible'
    clone.removeAttribute('aria-label')
    // Une iframe copiée rechargerait la page dans chaque bande : on la remplace par un aplat.
    clone.querySelectorAll('iframe').forEach((frame) => {
      const placeholder = document.createElement('div')
      placeholder.className = frame.className
      placeholder.style.background = 'var(--macos-finder-window)'
      frame.replaceWith(placeholder)
    })
    strip.append(clone)
    layer.append(strip)
    return strip
  })
  root.append(layer)

  // cloneNode ne copie pas la position de défilement : sans ça, une liste défilée repartirait du haut.
  strips.forEach((strip) => {
    const elements = strip.firstElementChild?.querySelectorAll<HTMLElement>('*')
    scrolled.forEach(({ index, top, left }) => {
      const element = elements?.[index]
      if (element) element.scrollTo(left, top)
    })
  })

  return { layer, strips, window, icon, progress: 0, frame: 0 }
}

function paint(run: GenieRun) {
  const shapes = genieStrips(run.window, run.icon, run.progress, run.strips.length)
  run.strips.forEach((strip, index) => {
    const { x, y, scaleX, scaleY, clip } = shapes[index]
    const percent = (value: number) => `${(value * 100).toFixed(3)}%`
    strip.style.transform = `translate(${x}px, ${y}px) scale(${scaleX}, ${scaleY})`
    strip.style.clipPath = `polygon(${percent(clip.topLeft)} 0, ${percent(clip.topRight)} 0, ${percent(clip.bottomRight)} 100%, ${percent(clip.bottomLeft)} 100%)`
  })
  run.layer.style.opacity = String(genieOpacity(run.progress))
}

// Effet « génie » de macOS : la fenêtre s'aspire dans son icône du Dock (minimize) ou en ressort (restore).
export function useGenie(
  sourceRef: RefObject<HTMLElement | null>,
  direction: GenieDirection | null,
  window: Rect,
  app: string,
  onDone: () => void,
) {
  const runRef = useRef<GenieRun | null>(null)
  const onDoneRef = useRef(onDone)
  const windowRef = useRef(window)

  useLayoutEffect(() => {
    onDoneRef.current = onDone
    windowRef.current = window
  })

  useLayoutEffect(() => {
    if (!direction) return
    const source = sourceRef.current
    const root = source?.closest<HTMLElement>('[data-macos-root]')
    const icon = root ? dockTargetRect(root, app) : null
    if (!source || !root || !icon) {
      onDoneRef.current()
      return
    }
    // Un changement de sens en cours de route repart de la progression atteinte, avec les mêmes bandes.
    const run =
      runRef.current ??
      Object.assign(buildLayer(source, root, windowRef.current, icon), { progress: direction === 'minimize' ? 0 : 1 })
    runRef.current = run
    const target = direction === 'minimize' ? 1 : 0
    let last = performance.now()
    paint(run)

    const tick = (now: number) => {
      const step = (now - last) / DURATION_MS
      last = now
      run.progress = target > run.progress ? Math.min(target, run.progress + step) : Math.max(target, run.progress - step)
      paint(run)
      if (run.progress === target) {
        run.layer.remove()
        runRef.current = null
        onDoneRef.current()
        return
      }
      run.frame = requestAnimationFrame(tick)
    }
    run.frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(run.frame)
  }, [direction, sourceRef, app])

  useEffect(
    () => () => {
      runRef.current?.layer.remove()
      runRef.current = null
    },
    [],
  )
}

import { useMemo } from 'react'
import { FILE_TREE_YEAR, MAC_FILE_TEXTS } from '@/data/macos'
import { PROJECTS, PROJECTS_SECTION } from '@/data/projects'
import { ROLES } from '@/data/roles'
import { useLocale } from '@/lib/LocaleProvider'
import { buildFileTree } from '@/logic/macos/buildFileTree/buildFileTree'

// Arborescence du Finder dans la langue du site, recalculée seulement quand la langue change.
export function useMacFiles() {
  const { locale } = useLocale()
  return useMemo(
    () =>
      buildFileTree({
        texts: MAC_FILE_TEXTS[locale],
        projects: PROJECTS[locale],
        roles: ROLES[locale],
        dateLabel: PROJECTS_SECTION[locale].dateLabel,
        year: FILE_TREE_YEAR,
      }),
    [locale],
  )
}

import { useEffect, useState } from 'react'
import { msUntilNextMinute } from '@/logic/macos/clock/clock'

// Heure locale rafraîchie pile au changement de minute.
export function useMinuteClock() {
  const [now, setNow] = useState(() => new Date())

  useEffect(() => {
    let timeoutId = 0
    const schedule = () => {
      timeoutId = window.setTimeout(() => {
        setNow(new Date())
        schedule()
      }, msUntilNextMinute(new Date()))
    }
    schedule()
    return () => window.clearTimeout(timeoutId)
  }, [])

  return now
}

import { Link } from 'react-router-dom'
import { motion } from 'framer-motion'

const MotionLink = motion.create(Link)

type NavPillProps = {
  label: string
  href: string
  onNavigate?: () => void
}

/* --pill-hover va de 0 (repos) à 1 (survol) sur le ressort de la réf. : le léger dépassement à la sortie éclaircit la pill un instant. */
export default function NavPill({ label, href, onNavigate }: NavPillProps) {
  return (
    <MotionLink
      to={href}
      onClick={onNavigate}
      initial={{ '--pill-hover': 0 }}
      whileHover={{ '--pill-hover': 1 }}
      whileTap={{ '--pill-hover': 1 }}
      transition={{ type: 'spring', bounce: 0.2, duration: 0.4 }}
      className="flex cursor-pointer items-center justify-center rounded-[50px] bg-[color-mix(in_srgb,var(--color-black)_clamp(0%,calc(6%_+_94%_*_var(--pill-hover)),100%),var(--color-white))] px-3 py-1.5 font-sans text-[18px] leading-[1.2] font-medium tracking-[-0.05em] whitespace-pre text-[color-mix(in_srgb,var(--color-white)_clamp(0%,calc(100%_*_var(--pill-hover)),100%),var(--color-black))]"
    >
      {label}
    </MotionLink>
