const SEEN_KEY = 'loader.seen'

// sessionStorage peut lever une erreur (navigation privée, stockage bloqué) : on retombe sur « pas vu ».
export function hasSeenLoader() {
  try {
    return window.sessionStorage.getItem(SEEN_KEY) === '1'
  } catch {
    return false
  }
}

export function markLoaderSeen() {
  try {
    window.sessionStorage.setItem(SEEN_KEY, '1')
  } catch {
    return
  }
}

// Page révélée dans cet onglet : le loader commence sa sortie une seule fois par chargement de l'app.
let isPageRevealed = false
const revealListeners = new Set<() => void>()

export function isLoaderRevealed() {
  return isPageRevealed
}

export function markLoaderRevealed() {
  if (isPageRevealed) return
  isPageRevealed = true
  revealListeners.forEach((listener) => listener())
}

export function subscribeLoaderReveal(listener: () => void) {
  revealListeners.add(listener)
  return () => {
    revealListeners.delete(listener)
  }
}

import type { Locale } from '@/data/locale'

const LOCALE_KEY = 'locale'

// localStorage peut lever une erreur (navigation privée, stockage bloqué) : on fait comme si rien n'était enregistré.
export function readStoredLocale() {
  try {
    return window.localStorage.getItem(LOCALE_KEY)
  } catch {
    return null
  }
}

export function storeLocale(locale: Locale) {
  try {
    window.localStorage.setItem(LOCALE_KEY, locale)
  } catch {
    return
  }
}

export type MacDisplay = { brightness: number; isDarkMode: boolean }

const DISPLAY_KEY = 'macos.display'
export const DEFAULT_MAC_DISPLAY: MacDisplay = { brightness: 1, isDarkMode: false }

// Luminosité et mode sombre du faux macOS, gardés pour la session. Stockage bloqué ou valeur abîmée : réglages par défaut.
export function readMacDisplay(): MacDisplay {
  try {
    const stored = JSON.parse(window.sessionStorage.getItem(DISPLAY_KEY) ?? 'null') as Partial<MacDisplay> | null
    if (!stored) return DEFAULT_MAC_DISPLAY
    return {
      brightness: typeof stored.brightness === 'number' ? stored.brightness : DEFAULT_MAC_DISPLAY.brightness,
      isDarkMode: typeof stored.isDarkMode === 'boolean' ? stored.isDarkMode : DEFAULT_MAC_DISPLAY.isDarkMode,
    }
  } catch {
    return DEFAULT_MAC_DISPLAY
  }
}

export function saveMacDisplay(display: MacDisplay) {
  try {
    window.sessionStorage.setItem(DISPLAY_KEY, JSON.stringify(display))
  } catch {
    return
  }
}

import { NOTE_COLORS, type PinnedNote } from '@/types/note'

// Contrat de stockage des notes : une implémentation lib/api/notes.ts (portfolio-backend) pourra remplacer localNotesStore.
export type NotesStore = {
  listNotes: () => Promise<PinnedNote[]>
  pinNote: (note: PinnedNote) => Promise<PinnedNote>
}

const NOTES_KEY = 'pinned-notes'

function isPinnedNote(value: unknown): value is PinnedNote {
  if (typeof value !== 'object' || value === null) return false
  const note = value as Record<string, unknown>
  return (
    typeof note.id === 'string' &&
    typeof note.text === 'string' &&
    (note.author === null || typeof note.author === 'string') &&
    NOTE_COLORS.includes(note.color as PinnedNote['color']) &&
    typeof note.createdAt === 'string'
  )
}

// localStorage peut lever une erreur (navigation privée, stockage bloqué) ou contenir autre chose : on repart d'une liste vide.
function readNotes(): PinnedNote[] {
  try {
    const parsed: unknown = JSON.parse(window.localStorage.getItem(NOTES_KEY) ?? '[]')
    return Array.isArray(parsed) ? parsed.filter(isPinnedNote) : []
  } catch {
    return []
  }
}

export const localNotesStore: NotesStore = {
  listNotes: async () => readNotes(),
  pinNote: async (note) => {
    try {
      window.localStorage.setItem(NOTES_KEY, JSON.stringify([note, ...readNotes()]))
    } catch {
      return note
    }
    return note
  },
}

import { describe, expect, it } from 'vitest'
import { coverBox, coverDistance, fitDistance } from '@/logic/cameraFit/cameraFit'

describe('fitDistance', () => {
  it('cadre sur la hauteur quand l’écran est plus large que le rectangle', () => {
    const square = { width: 2, height: 2 }
    const wideLens = { verticalFovDeg: 90, aspect: 2 }

    expect(fitDistance(square, wideLens)).toBeCloseTo(1)
  })

  it('cadre sur la largeur quand l’écran est en portrait', () => {
    const square = { width: 2, height: 2 }
    const portraitLens = { verticalFovDeg: 90, aspect: 0.5 }

    expect(fitDistance(square, portraitLens)).toBeCloseTo(2)
  })

  it('recule proportionnellement à la marge', () => {
    const square = { width: 2, height: 2 }
    const lens = { verticalFovDeg: 90, aspect: 1 }

    expect(fitDistance(square, lens, 1.5)).toBeCloseTo(1.5)
  })
})

describe('coverDistance', () => {
  it('cadre sur la largeur quand le cadre est plus large que le rectangle', () => {
    const square = { width: 2, height: 2 }
    const wideLens = { verticalFovDeg: 90, aspect: 2 }

    expect(coverDistance(square, wideLens)).toBeCloseTo(0.5)
  })

  it('cadre sur la hauteur quand le cadre est en portrait', () => {
    const square = { width: 2, height: 2 }
    const portraitLens = { verticalFovDeg: 90, aspect: 0.5 }

    expect(coverDistance(square, portraitLens)).toBeCloseTo(1)
  })
})

describe('coverBox', () => {
  it('garde toute la largeur et rogne la hauteur sur un cadre plus large', () => {
    const macScreen = { width: 1512, height: 982 }
    const desktopAspect = 1.6

    expect(coverBox(macScreen, desktopAspect, 1024)).toEqual({ width: 1512, height: 945, scale: 1 })
  })

  it('agrandit la zone logique et la réduit quand la partie visible est trop étroite', () => {
