// Courbe de la barre de démarrage de macweb.dev (MIT) : pourcentage de 0 à 100 selon le temps écoulé en ms.
export function bootProgressAt(elapsed: number): number {
  let progress: number
  if (elapsed < 800) progress = Math.min(30, (elapsed / 800) * 30)
  else if (elapsed < 2200) {
    progress = 30 + Math.min(55, ((elapsed - 800) / 1400) * 55)
    // 2 accrocs volontaires de l'original, pour que la barre ne file pas d'un trait.
    if (progress > 45 && progress < 47) progress = 45.5
    if (progress > 70 && progress < 72) progress = 71
  } else if (elapsed < 2800) progress = 85 + Math.min(10, ((elapsed - 2200) / 600) * 10)
  else progress = 95 + Math.min(5, ((elapsed - 2800) / 400) * 5)
  return Math.min(100, Math.floor(progress * 10) / 10)
}

import { describe, expect, it } from 'vitest'
import { brightnessShade } from '@/logic/macos/brightness/brightness'

describe('brightnessShade', () => {
  it('ne voile pas l’écran à pleine luminosité', () => {
    const fullBrightness = 1

    expect(brightnessShade(fullBrightness)).toBe(0)
  })

  it('voile l’écran à 85 % au minimum de luminosité', () => {
    const lowestBrightness = 0

    expect(brightnessShade(lowestBrightness)).toBe(0.85)
  })

  it('assombrit proportionnellement entre les deux', () => {
    const halfBrightness = 0.5

    expect(brightnessShade(halfBrightness)).toBe(0.425)
  })

  it('borne une luminosité hors plage', () => {
    const tooBright = 1.4

    expect(brightnessShade(tooBright)).toBe(0)
  })
})

// Au minimum de luminosité, l'écran reste lisible : le voile noir ne dépasse pas 85 % d'opacité, comme un vrai Mac.
const MAX_SHADE = 0.85

export function brightnessShade(brightness: number) {
  const clamped = Math.min(Math.max(brightness, 0), 1)
  return Math.round((1 - clamped) * MAX_SHADE * 1000) / 1000
}

