import type { Rect } from '@/logic/macos/windowBounds/windowBounds'

// Bord gauche et droit du haut et du bas d'une bande, en fraction de sa largeur affichée.
export type GenieClip = { topLeft: number; topRight: number; bottomLeft: number; bottomRight: number }

// Bande horizontale de la fenêtre : translation puis échelle depuis le coin haut gauche (transform-origin 0 0),
// puis découpe en trapèze pour que les bords de l'entonnoir restent lisses d'une bande à l'autre.
export type GenieStrip = { x: number; y: number; scaleX: number; scaleY: number; clip: GenieClip }

// Part de l'animation où la fenêtre se tord en entonnoir avant de glisser dans l'icône, comme macOS.
const BEND_SHARE = 0.35
const FADE_START = 0.86
const STRIP_HEIGHT = 18
const MIN_STRIPS = 12
const MAX_STRIPS = 40

function clamp01(value: number) {
  return Math.min(Math.max(value, 0), 1)
}

function lerp(from: number, to: number, amount: number) {
  return from + (to - from) * amount
}

function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2
}

function smoothstep(t: number) {
  return t * t * (3 - 2 * t)
}

export function genieStripCount(windowHeight: number) {
  return Math.min(Math.max(Math.round(windowHeight / STRIP_HEIGHT), MIN_STRIPS), MAX_STRIPS)
}

// progress 0 : fenêtre intacte. 1 : fenêtre logée dans l'icône du Dock.
export function genieStrips(window: Rect, icon: Rect, progress: number, count: number): GenieStrip[] {
  const p = clamp01(progress)
  const bend = easeInOutCubic(clamp01(p / BEND_SHARE))
  const slide = easeInOutCubic(clamp01((p - BEND_SHARE) / (1 - BEND_SHARE)))
  const funnelHeight = Math.max(1, icon.y - window.y)
  const stripHeight = window.height / count

  const rowY = (v: number) => lerp(window.y + v * window.height, icon.y + v * icon.height, slide)
  // Plus une ligne est basse, plus ses bords se rapprochent de ceux de l'icône.
  const edgesAt = (y: number) => {
    const pinch = smoothstep(clamp01((y - window.y) / funnelHeight)) * bend
    return {
      left: lerp(window.x, icon.x, pinch),
      right: lerp(window.x + window.width, icon.x + icon.width, pinch),
    }
  }

  return Array.from({ length: count }, (_, index) => {
    const top = rowY(index / count)
    const bottom = rowY((index + 1) / count)
    const topEdges = edgesAt(top)
    const bottomEdges = edgesAt(bottom)
    const left = Math.min(topEdges.left, bottomEdges.left)
    const right = Math.max(topEdges.right, bottomEdges.right)
    const width = Math.max(right - left, 1e-6)
    const fraction = (x: number) => (x - left) / width
    return {
      x: left,
      y: top,
      scaleX: (right - left) / window.width,
      scaleY: (bottom - top) / stripHeight,
      clip: {
        topLeft: fraction(topEdges.left),
        topRight: fraction(topEdges.right),
        bottomLeft: fraction(bottomEdges.left),
        bottomRight: fraction(bottomEdges.right),
      },
    }
  })
}

// Fondu tout à la fin seulement, pour que la fenêtre disparaisse dans l'icône sans saut.
export function genieOpacity(progress: number) {
  return 1 - clamp01((clamp01(progress) - FADE_START) / (1 - FADE_START))
}

import { describe, expect, it } from 'vitest'
import {
  canGoBack,
  canGoForward,
  createHistory,
  currentEntry,
  goBack,
  goForward,
  pushEntry,
} from '@/logic/macos/navigationHistory/navigationHistory'

describe('navigationHistory', () => {
  it('démarre sur l’entrée initiale, sans retour ni suivant', () => {
    const freshHistory = createHistory('desktop')

    expect(currentEntry(freshHistory)).toBe('desktop')
    expect(canGoBack(freshHistory)).toBe(false)
    expect(canGoForward(freshHistory)).toBe(false)
  })

  it('revient en arrière puis repart en avant', () => {
    const historyInProjects = pushEntry(createHistory('desktop'), 'projects')

    const historyAfterBack = goBack(historyInProjects)
    const historyAfterForward = goForward(historyAfterBack)

    expect(currentEntry(historyAfterBack)).toBe('desktop')
    expect(currentEntry(historyAfterForward)).toBe('projects')
  })

  it('efface les entrées suivantes quand on navigue après un retour', () => {
    const historyBackOnDesktop = goBack(pushEntry(createHistory('desktop'), 'projects'))

    const historyInDownloads = pushEntry(historyBackOnDesktop, 'downloads')

    expect(historyInDownloads.entries).toEqual(['desktop', 'downloads'])
    expect(canGoForward(historyInDownloads)).toBe(false)
  })

  it('ne bouge pas quand on recule au début', () => {
    const freshHistory = createHistory('desktop')

    expect(goBack(freshHistory)).toBe(freshHistory)
  })
})

export type NavigationHistory<T> = { entries: T[]; index: number }

export function createHistory<T>(initial: T): NavigationHistory<T> {
  return { entries: [initial], index: 0 }
}

export function currentEntry<T>(history: NavigationHistory<T>): T {
  return history.entries[history.index]
}

// Naviguer après un retour efface les pages « suivantes », comme dans un navigateur.
export function pushEntry<T>(history: NavigationHistory<T>, entry: T): NavigationHistory<T> {
  return { entries: [...history.entries.slice(0, history.index + 1), entry], index: history.index + 1 }
}

export function canGoBack<T>(history: NavigationHistory<T>) {
  return history.index > 0
}

export function canGoForward<T>(history: NavigationHistory<T>) {
  return history.index < history.entries.length - 1
}

export function goBack<T>(history: NavigationHistory<T>): NavigationHistory<T> {
  return canGoBack(history) ? { ...history, index: history.index - 1 } : history
}

export function goForward<T>(history: NavigationHistory<T>): NavigationHistory<T> {
  return canGoForward(history) ? { ...history, index: history.index + 1 } : history
}

